-- ============================================================================
-- Weeks 1–4 authoring specs and assessment specs (generated)
-- Edit the JSON under content/curriculum, then run:
--   node supabase-b1-b2/scripts/build-details-seed.mjs
-- ============================================================================

create table if not exists public.syllabus_week_details (
  week_number int primary key references public.syllabus_weeks(week_number) on delete cascade,
  payload jsonb not null
);

create table if not exists public.syllabus_assessments (
  code text primary key,
  title text not null,
  payload jsonb not null
);

create table if not exists public.syllabus_vocab_items (
  id text primary key,
  week_number int not null references public.syllabus_weeks(week_number) on delete cascade,
  group_kind text not null check (group_kind in ('core', 'collocation', 'family', 'optional', 'linker')),
  target text not null,
  cefr text,
  use_role text,
  example text not null,
  card text not null,
  sort_order int not null
);

create table if not exists public.syllabus_grammar_items (
  id text primary key,
  week_number int not null references public.syllabus_weeks(week_number) on delete cascade,
  step text not null,
  target text not null,
  payload jsonb not null,
  sort_order int not null
);

create table if not exists public.syllabus_input_items (
  id text primary key,
  week_number int not null references public.syllabus_weeks(week_number) on delete cascade,
  mode text not null check (mode in ('listening', 'reading')),
  step text not null,
  payload jsonb not null,
  sort_order int not null
);

create table if not exists public.syllabus_checkpoint_items (
  id text primary key,
  week_number int not null references public.syllabus_weeks(week_number) on delete cascade,
  reserve boolean not null default false,
  target text not null,
  prompt text not null,
  options jsonb not null default '[]'::jsonb,
  key text not null,
  reason text not null,
  sort_order int not null
);

alter table public.syllabus_week_details enable row level security;
drop policy if exists "syllabus_week_details_public_read" on public.syllabus_week_details;
create policy "syllabus_week_details_public_read" on public.syllabus_week_details for select to anon, authenticated using (true);
grant select on public.syllabus_week_details to anon, authenticated;
alter table public.syllabus_assessments enable row level security;
drop policy if exists "syllabus_assessments_public_read" on public.syllabus_assessments;
create policy "syllabus_assessments_public_read" on public.syllabus_assessments for select to anon, authenticated using (true);
grant select on public.syllabus_assessments to anon, authenticated;
alter table public.syllabus_vocab_items enable row level security;
drop policy if exists "syllabus_vocab_items_public_read" on public.syllabus_vocab_items;
create policy "syllabus_vocab_items_public_read" on public.syllabus_vocab_items for select to anon, authenticated using (true);
grant select on public.syllabus_vocab_items to anon, authenticated;
alter table public.syllabus_grammar_items enable row level security;
drop policy if exists "syllabus_grammar_items_public_read" on public.syllabus_grammar_items;
create policy "syllabus_grammar_items_public_read" on public.syllabus_grammar_items for select to anon, authenticated using (true);
grant select on public.syllabus_grammar_items to anon, authenticated;
alter table public.syllabus_input_items enable row level security;
drop policy if exists "syllabus_input_items_public_read" on public.syllabus_input_items;
create policy "syllabus_input_items_public_read" on public.syllabus_input_items for select to anon, authenticated using (true);
grant select on public.syllabus_input_items to anon, authenticated;
alter table public.syllabus_checkpoint_items enable row level security;
drop policy if exists "syllabus_checkpoint_items_public_read" on public.syllabus_checkpoint_items;
create policy "syllabus_checkpoint_items_public_read" on public.syllabus_checkpoint_items for select to anon, authenticated using (true);
grant select on public.syllabus_checkpoint_items to anon, authenticated;

insert into public.syllabus_week_details (week_number, payload)
select (week.value->>'number')::int, week.value
from jsonb_array_elements('{"version":"2026-11-21","sources":["Revised grammar plan — Weeks 1–4, syllabus aligned (21 Nov 2026)","Vocabulary review — Weeks 1–4, syllabus aligned (21 Nov 2026)","Course syllabus (21 Nov 2026)","Fluency Studio: Weeks 1–4 Grammar Practice Item Bank (21 Nov 2026)","Fluency Studio: Weeks 1–4 Speaking Content (21 Nov 2026)","Fluency Studio: Weeks 1–4 Listening Content (21 Nov 2026)","Fluency Studio: Weeks 1–4 Reading Content (21 Nov 2026)","Fluency Studio: Writing Content, Weeks 1–4 (21 Nov 2026)","Fluency Studio: Writing Content, Weeks 1–4 (21 Nov 2026)"],"pilotRules":{"grammarTask":{"minutes":20,"autoMarkedItems":25,"breakdown":[{"type":"meaning checks","count":3},{"type":"choose","count":6},{"type":"complete","count":5},{"type":"fix","count":3},{"type":"rewrite","count":3},{"type":"light items","count":3},{"type":"review items","count":2}],"personalSentences":2,"extraItemsBelow60":3,"skipRewriteAt90Plus":true,"steps":[{"step":1,"name":"Notice the forms in a short text","minutes":2,"items":null},{"step":2,"name":"Meaning checks","minutes":2,"items":3},{"step":3,"name":"Choose","minutes":3,"items":6},{"step":4,"name":"Complete","minutes":3,"items":5},{"step":5,"name":"Fix","minutes":2,"items":3},{"step":6,"name":"Rewrite","minutes":2,"items":3},{"step":7,"name":"Light items","minutes":2,"items":3},{"step":8,"name":"Sentences of your own with AI feedback","minutes":3,"items":null},{"step":9,"name":"Review items","minutes":1,"items":2}]},"speaking":"Record 60–90 seconds. Hide the model before the first take. One specific AI correction, then record again straight away.","writing":"30 minutes, 120–150 words, instant AI feedback and revise-and-retry. A few days later a new speaking prompt without the phrase bank.","conversation":"15 minutes recommended; 3–4 turns with the AI partner on the week''s theme, grammar and featured words. Feedback after the exchange, then one turn retried.","extensiveInput":"About 60 minutes a week of graded B1 listening or reading with transcripts or captions, tagged to the week''s theme; 40 minutes recommended; up to 5 personal words.","progression":"No fixed days or deadlines. The next week opens when speaking, writing and either listening or reading are done.","level":"Adults and older teenagers (16+) at secure B1. Adult contexts: work, flat-sharing, plans and travel. Judge control and clarity, not the number of forms used.","grammarClinic":"Only syllabus B1 basics: present simple and continuous, articles, quantifiers, prepositions, subject–verb agreement and verb forms. Every Light point is taught in its own week, not moved to the clinic."},"conversationRules":{"levelAndTurns":"The partner speaks at B1 in one- or two-sentence turns and asks one follow-up per turn. Ends after 3–4 learner turns, or earlier on request.","errors":"No interruption or mid-conversation corrections; natural recasts only, e.g. ''Oh, you''ve lived there since May?''","feedback":"After the exchange: up to three corrections prioritising the week''s grammar, one featured word used well or one that would have fitted, then one turn retried.","labelledAsAi":"The partner and its feedback are always labelled as AI; learners can dispute feedback with ''I think this is right''.","accent":"Feedback covers grammar, vocabulary and clarity. A Spanish or regional accent is never an error; misrecognised words are not grammar mistakes.","safety":"Stays on the week''s theme, declines romantic, sexual, harmful or personal-data topics, never asks for an address or phone number, suitable for ages 16–17, report button on every exchange, transcripts kept under the privacy policy."},"weeks":[{"number":1,"title":"A change you got used to","canDo":"Tell a story about a change: set the scene, sequence events and connect them to now.","featuredVocabulary":["face a challenge","get used to + noun or -ing","since then"],"stretchPhrases":["gradually","look back on"],"grammar":{"main":"narrative tenses; present perfect vs past simple.","light":"used to / would; present perfect continuous.","sampleItems":[],"authoringNote":"Would for past habits is not normally used in negatives, questions or states; accept used to or the past simple there, and don''t flag the past simple where used to is possible. Contrast result (''I''ve made a few friends'') and activity (''I''ve been running'').","practice":{"status":"pilot draft — pending second-teacher review","durationMinutes":20,"notice":{"text":"Three years ago, I moved to Bristol for work. I had never lived abroad before, so the first months were hard. One morning, while I was waiting for the bus, I started chatting to a neighbour. She invited me to a book club. We used to meet every Thursday, and we would always argue about the ending! I have lived here for three years now, and I''ve been going to that club ever since.","targetForms":"six","markedBy":"App"},"steps":[{"step":1,"exercise":"Notice: listen to and read a short text, tap the target forms","items":"1 text","time":"2 min","markedBy":"App"},{"step":2,"exercise":"Check the meaning: short questions about what the form means","items":3,"time":"2 min","markedBy":"App"},{"step":3,"exercise":"Choose in context: two options","items":6,"time":"3 min","markedBy":"App"},{"step":4,"exercise":"Complete: verb or prompt in brackets","items":5,"time":"3 min","markedBy":"App"},{"step":5,"exercise":"Find and fix the mistake","items":3,"time":"2 min","markedBy":"App"},{"step":6,"exercise":"Rewrite with the target form","items":3,"time":"2 min","markedBy":"App, with AI checking other correct answers"},{"step":7,"exercise":"Light point: choose or reorder","items":3,"time":"2 min","markedBy":"App"},{"step":8,"exercise":"Use it yourself: two sentences about your own life, spoken or typed","items":2,"time":"3 min","markedBy":"AI, instant feedback and one retry"},{"step":9,"exercise":"Spaced review: earlier grammar","items":2,"time":"1 min","markedBy":"App"}],"extraPractice":"Each week has 3 extra items. A learner who scores below 60% on steps 3-4 gets them before moving on; a learner who scores 90% or more on steps 3-4 skips step 6.","feedback":"Every item has a one-line reason, shown straight after the answer. Wrong answers become review cards. In steps 6 and 8 the AI accepts any correct answer that uses the target form, not only the key.","itemFormat":"Each item has an id, a step, a target (Main, Light or Review), the prompt, the options where there are any, the key, accepted variants, and the reason.","week1Review":"There is no earlier course grammar in Week 1, so its review items come from the grammar clinic (present simple vs continuous, articles).","items":[{"id":"W1-M1","step":"Meaning","target":"Main","prompt":"\"I had never lived abroad before.\" Had the speaker lived abroad before moving to Bristol?","options":["Yes","No"],"key":"No","accepted":[],"reason":"The past perfect describes the situation before the move."},{"id":"W1-M2","step":"Meaning","target":"Main","prompt":"\"While I was waiting for the bus, I started chatting.\" Which action was in the background?","options":["waiting","chatting"],"key":"waiting","accepted":[],"reason":"The past continuous sets the scene; the past simple is the event."},{"id":"W1-M3","step":"Meaning","target":"Main","prompt":"\"I have lived here for three years.\" Does the speaker still live in Bristol?","options":["Yes","No"],"key":"Yes","accepted":[],"reason":"The present perfect connects the past to now."},{"id":"W1-C1","step":"Choose","target":"Main","prompt":"I ___ to Bristol three years ago.","options":["moved","have moved"],"key":"moved","accepted":[],"reason":"\"Three years ago\" is a finished time."},{"id":"W1-C2","step":"Choose","target":"Main","prompt":"I ___ a lot of new friends since then.","options":["made","have made"],"key":"have made","accepted":[],"reason":"\"Since then\" means up to now."},{"id":"W1-C3","step":"Choose","target":"Main","prompt":"When I arrived at the station, the train ___.","options":["left","had left"],"key":"had left","accepted":[],"reason":"It left before I arrived."},{"id":"W1-C4","step":"Choose","target":"Main","prompt":"I ___ dinner when my phone rang.","options":["was cooking","cooked"],"key":"was cooking","accepted":[],"reason":"A longer action interrupted by a short one."},{"id":"W1-C5","step":"Choose","target":"Main","prompt":"___ you ever ___ in another country?","options":["Did ... live","Have ... lived"],"key":["Have","lived"],"accepted":[[],[]],"reason":"\"Ever\" asks about life experience up to now."},{"id":"W1-C6","step":"Choose","target":"Main","prompt":"She ___ her job last month and is now looking for a new one.","options":["has left","left"],"key":"left","accepted":[],"reason":"\"Last month\" is a finished time."},{"id":"W1-G1","step":"Complete","target":"Main","prompt":"While we ___ (drive) to the coast, it started to rain.","options":[],"key":"were driving","accepted":[],"reason":"Background action."},{"id":"W1-G2","step":"Complete","target":"Main","prompt":"By the time I got to the party, most people ___ (go) home.","options":[],"key":"had gone","accepted":[],"reason":"They left before I arrived."},{"id":"W1-G3","step":"Complete","target":"Main","prompt":"I ___ (know) Maria since we were at school.","options":[],"key":"have known","accepted":[],"reason":"Up to now with \"since\"; know is not used in the continuous."},{"id":"W1-G4","step":"Complete","target":"Main","prompt":"Last summer I ___ (spend) two weeks in Scotland.","options":[],"key":"spent","accepted":[],"reason":"Finished time."},{"id":"W1-G5","step":"Complete","target":"Main","prompt":"She was tired because she ___ (not sleep) the night before.","options":[],"key":"hadn''t slept","accepted":["had not slept"],"reason":"Earlier than the moment she was tired."},{"id":"W1-F1","step":"Fix","target":"Main","prompt":"I have moved to Leeds in 2023.","options":[],"key":"I moved to Leeds in 2023.","accepted":[],"reason":"\"In 2023\" is a finished time, so use the past simple."},{"id":"W1-F2","step":"Fix","target":"Main","prompt":"When I got home, my flatmate already cooked dinner.","options":[],"key":"When I got home, my flatmate had already cooked dinner.","accepted":[],"reason":"Cooking happened before I got home."},{"id":"W1-F3","step":"Fix","target":"Main","prompt":"I was knowing her for years before we worked together.","options":[],"key":"I had known her for years before we worked together.","accepted":[],"reason":"Know is a state verb, and this happened before the other past event."},{"id":"W1-R1","step":"Rewrite","target":"Main","prompt":"I started learning English in 2020. I''m still learning it. (since)","options":[],"key":"I''ve been learning English since 2020.","accepted":["I have been learning English since 2020."],"reason":"An activity that continues up to now."},{"id":"W1-R2","step":"Rewrite","target":"Main","prompt":"First the film started. Then we arrived. (When ... already)","options":[],"key":"When we arrived, the film had already started.","accepted":["The film had already started when we arrived."],"reason":"The past perfect shows which happened first."},{"id":"W1-R3","step":"Rewrite","target":"Main","prompt":"I was walking home. I saw an accident. (While)","options":[],"key":"While I was walking home, I saw an accident.","accepted":["I saw an accident while I was walking home."],"reason":"Background plus event."},{"id":"W1-L1","step":"Light","target":"Light","prompt":"When I was a child, we ___ in a small flat.","options":["used to live","would live"],"key":"used to live","accepted":[],"reason":"Live is a state, so would is not possible."},{"id":"W1-L2","step":"Light","target":"Light","prompt":"Every summer, my grandfather ___ us fishing.","options":["would take","has taken"],"key":"would take","accepted":["used to take"],"reason":"A repeated action in the past."},{"id":"W1-L3","step":"Light","target":"Light","prompt":"I''m tired because I ___ all morning.","options":["''ve been studying","study"],"key":"''ve been studying","accepted":[],"reason":"An activity up to now with a result you can see."},{"id":"W1-U1","step":"Use it","target":"Main","prompt":"Tell me about something you used to do as a child that you don''t do now.","options":[],"key":"Any correct sentence with used to or would","accepted":[],"reason":"AI checks the form and gives one correction."},{"id":"W1-U2","step":"Use it","target":"Main","prompt":"What has changed in your life since you started your current job or studies?","options":[],"key":"Any correct sentence with the present perfect and since","accepted":[],"reason":"AI checks the form and gives one correction."},{"id":"W1-V1","step":"Review (clinic)","target":"Review","prompt":"I usually ___ to work, but this week I''m working from home.","options":["walk","am walking"],"key":"walk","accepted":[],"reason":"A usual habit uses the present simple."},{"id":"W1-V2","step":"Review (clinic)","target":"Review","prompt":"She''s ___ engineer.","options":["a","an"],"key":"an","accepted":[],"reason":"Use an before a vowel sound."},{"id":"W1-E1","step":"Extra","target":"Extra","prompt":"We ___ (watch) TV when the lights went out.","options":[],"key":"were watching","accepted":[],"reason":"Background action interrupted."},{"id":"W1-E2","step":"Extra","target":"Extra","prompt":"I ___ (never / see) snow until I moved to Canada.","options":[],"key":"had never seen","accepted":[],"reason":"Before another past event."},{"id":"W1-E3","step":"Extra","target":"Extra","prompt":"She ___ (work) here since 2019.","options":[],"key":"has worked","accepted":["has been working"],"reason":"Up to now with \"since\"; both forms are correct."}]}},"speaking":{"status":"pilot draft — pending second-teacher review","main":"narrative tenses; present perfect vs past simple.","light":"used to / would; present perfect continuous.","featured":["face a challenge","get used to","since then (stretch: gradually","look back on)."],"flow":{"shadowingWarmup":"3 min; listen to three short chunks from the model answer at normal and slower speed, repeat each, then compare your recording with the model. Self-check against a short prosody checklist; never scored.","plan":"2 min; read the cue card, note key words if you like; the model answer is hidden.","record":"60-90 s; one recording covering every cue point; AI marked against the descriptors.","feedbackAndRetry":"5 min; a band for each criterion, one strength, one specific correction; then record again, with the model available to compare. AI; a teacher confirms flagged recordings.","conversation":"Any time in the week (recommended); 15 min; 3-4 learner turns with the AI partner, then feedback and one retried turn; AI.","unlocking":"The speaking task counts once the first recording is submitted; the retry is encouraged, not required."},"prompt":"Tell me about a change in your life. What was life like before? What changed, what was difficult, what helped, and what is different now?","cueCard":"Before · The change · What was hard · What helped · Now","phraseBank":["In my old town, I used to... / we would...","The biggest challenge I faced was...","It took me a while to get used to...","I''d never... before","While I was..., I...","Since then, I''ve...","I''ve been ...ing for...","When I look back on..., I..."],"model":"> When I moved to a new city last year, I didn''t know anyone. In my old town, I used to see my friends every weekend, and we would often cook together on Sunday evenings. So the biggest challenge I faced was meeting people outside work. It took me a few weeks to get used to spending my evenings alone. One evening, while I was walking home, I saw a poster for a running group. I''d never run with a group before, so I was nervous at the first session, but I gradually got to know the other runners. Since then, I''ve made a few friends, and the city feels more like home. I''ve been running with the group for about six months now. When I look back on those first few weeks, I''m really glad I went to that first session.","onTarget":"covers all five cue points; uses the past perfect or past continuous at least once and the present perfect at least once; uses two featured items.","correctionPriority":"1) past simple vs present perfect with time words (last year, since); 2) would with states (would live); 3) the -ing form after get used to.","shadowingChunks":[{"chunk":"It took me a few weeks to get used to it.","listenFor":"used to sounds like \"yoosta\"; stress on weeks and used"},{"chunk":"I''d never run with a group before.","listenFor":"the short I''d; stress on never, run and group"},{"chunk":"Since then, I''ve made a few friends.","listenFor":"I''ve is short; made_a links together"}],"conversation":{"title":"catching up with an old friend","turns":[{"partner":"It''s been ages! What''s changed since I last saw you?","learner":"Name a change (past simple, present perfect)","followUp":"Oh really? When did that happen?"},{"partner":"Wow. Was it hard at first?","learner":"Describe a challenge (past continuous or past perfect; face a challenge)","followUp":"What was the hardest part?"},{"partner":"So how are things now?","learner":"Say what is different now (present perfect, since then, present perfect continuous)","followUp":"How long have you been doing that?"},{"partner":"Do you miss anything about your old life?","learner":"Describe old habits (used to, would)","followUp":"What did you use to do at weekends?"}],"closingLine":"It''s great to hear you''re doing well. Let''s not leave it so long next time!","naturalRecastExample":"learner \"I have moved here last year.\" Partner: \"Oh, you moved here last year? I didn''t know!\""},"delayedRecall":"Tell me about a new routine that felt strange at first. What helped it feel normal?","b2Stretch":"explain why the change mattered and how you feel about it now, without the cue card."},"writing":{"status":"pilot draft — pending second-teacher review","title":"A change I got used to","durationMinutes":30,"words":[120,150],"prompt":"Write a personal narrative about a change in your life. Set the scene, use since then or eventually to move the story on, and close with one sentence about how things are now.","grammar":"narrative tenses; present perfect vs past simple; used to / would; present perfect continuous","featuredWords":["face a challenge","get used to","since then"],"stretchWords":["gradually","look back on"],"linkers":["since then","eventually"],"readerAndPurpose":"A blog post for readers who don’t know you. The aim is to tell a clear story with a beginning, middle and end.","requiredPoints":["How life was before the change","What changed and what was difficult","What helped","How things are now (final sentence)","since then or eventually used at least once"],"planFrame":["Before: where you were and what you used to do","The change and the biggest challenge","What helped, and how things moved on","Now: one sentence about today"],"usefulLanguage":["When I..., I had never... before","I used to... / We would...","The biggest challenge I faced was...","It took me a while to get used to...","Eventually,...","Since then, I’ve...","I’ve been ...ing for...","Now..."],"onTarget":"covers every required point; uses the past perfect or past continuous once and the present perfect once; uses two featured items; organises the story in a clear order.","correctionPriority":"1) past simple vs present perfect with time words (I have moved in 2020); 2) would with states (would live); 3) the -ing form after get used to.","reviseAndRetryFocus":"Add one sentence with the past perfect or past continuous to set the scene, and check every finished time (last year, in 2020) uses the past simple.","modelAnswer":"When I finished university, I moved from a small village to the city for my first job. I had never lived alone before, and at first everything felt strange. In the village, I used to know everyone, and my neighbours would often stop to chat. In the city, nobody said hello.\n\nThe biggest challenge I faced was cooking for myself. For the first few weeks, I ate takeaways almost every night! Then my flatmate’s mum gave me a simple recipe book, and I started to try one new dish every weekend.\n\nEventually, I got used to my new routine. Since then, I’ve learnt to cook about twenty dishes, and I’ve been inviting friends round for dinner every month. Now the city feels like home, and I’m proud of how much I’ve changed.","delayedRecall":"Tell me about a new routine that felt strange at first. What helped it feel normal?","pairedReading":"\"A year in Manchester\" (blog post)"},"conversation":{"scenario":"Catching up with an old friend.","openingLine":"It''s been ages! What''s changed since I last saw you?","learnerMoves":"Describe one change, what was hard and how life is now; answer one follow-up.","targetLanguage":"Narrative tenses, present perfect vs past simple, used to / would; face a challenge, get used to, since then"},"vocabulary":{"core":[{"target":"adapt","type":"v.","cefr":"B2","use":"B","example":"I had to adapt to living abroad."},{"target":"turning point","type":"n. phr.","cefr":"B2*","use":"B","example":"Moving to Leeds was a turning point in my life."},{"target":"challenge","type":"n.","cefr":"B1","use":"P","example":"I faced several challenges while I was studying abroad."},{"target":"get used to","type":"v. phr.","cefr":"B1","use":"P","example":"It took me a month to get used to living alone."},{"target":"look back on","type":"mw. v.","cefr":"B2*","use":"B","example":"When I look back on my first year abroad, I remember the people I met."},{"target":"regret","type":"v.","cefr":"B1","use":"P","example":"I''ve never regretted leaving my old job."},{"target":"gradually","type":"adv.","cefr":"B2*","use":"B","example":"My English gradually improved while I was living in York."},{"target":"memorable","type":"adj.","cefr":"B2*","use":"B","example":"Travelling alone was a memorable experience."}],"collocations":[{"target":"make a big decision","example":"I made a big decision about my future."},{"target":"take a risk","example":"I took a risk and applied for a job abroad."},{"target":"make a change","example":"I decided to make a change and cycle to work."},{"target":"keep in touch","example":"I''ve kept in touch with my old school friends."},{"target":"make progress","example":"I''ve been making good progress since September."},{"target":"take up","example":"I took up photography after I moved."}],"families":[{"base":"make a big decision","forms":["decision","decisive","indecisive"],"card":"decision is productive on the collocation card; decisive and indecisive recognition only"},{"base":"adapt","forms":["adaptable"],"card":"recognition only"},{"base":"make a change","forms":["unchanged"],"card":"recognition only"}],"optional":[],"newCards":14,"note":"Teach get used to + noun or -ing for B1 production; contrast used to + infinitive on the same card. Keep adapt to as guided B2."},"linkers":[{"target":"eventually","cefr":"B2","function":"time","taughtIn":"writing task","example":"Eventually, I got used to it."},{"target":"since then","cefr":"B1*","function":"time","taughtIn":"writing task","example":"I moved in September. Since then, I''ve made some good friends."}],"checkpoint1":{"mainItems":4,"lightItems":1,"focus":"Finished time, past-to-now, past continuous background, past perfect sequence; Light: used to / would"}},{"number":2,"title":"A goal and the next step","canDo":"Describe an intention, name an arrangement, say what happens next and what you''ll do if plans change.","featuredVocabulary":["goal","intend to","career","look forward to + noun or -ing"],"stretchPhrases":[],"grammar":{"main":"future forms.","light":"conditionals 0-2 (review).","sampleItems":[],"authoringNote":"''I will see my dentist tomorrow'' is grammatical; don''t flag it just because the visit is booked. Accept will or going to for predictions with present evidence. Conditional labels are teaching aids: accept natural variants such as ''when'' in a zero conditional.","practice":{"status":"pilot draft — pending second-teacher review","durationMinutes":20,"notice":{"text":"My goal this year is to get a better job. I''m going to update my CV this weekend, and I''m meeting a careers adviser on Tuesday. The course I want starts on 3 March. I think it''ll be hard, but when I finish it, I''ll apply for jobs in marketing. If I don''t get an interview, I''ll ask for feedback. And if I had more time, I''d study full-time!","targetForms":"seven","markedBy":"App"},"steps":[{"step":1,"exercise":"Notice: listen to and read a short text, tap the target forms","items":"1 text","time":"2 min","markedBy":"App"},{"step":2,"exercise":"Check the meaning: short questions about what the form means","items":3,"time":"2 min","markedBy":"App"},{"step":3,"exercise":"Choose in context: two options","items":6,"time":"3 min","markedBy":"App"},{"step":4,"exercise":"Complete: verb or prompt in brackets","items":5,"time":"3 min","markedBy":"App"},{"step":5,"exercise":"Find and fix the mistake","items":3,"time":"2 min","markedBy":"App"},{"step":6,"exercise":"Rewrite with the target form","items":3,"time":"2 min","markedBy":"App, with AI checking other correct answers"},{"step":7,"exercise":"Light point: choose or reorder","items":3,"time":"2 min","markedBy":"App"},{"step":8,"exercise":"Use it yourself: two sentences about your own life, spoken or typed","items":2,"time":"3 min","markedBy":"AI, instant feedback and one retry"},{"step":9,"exercise":"Spaced review: earlier grammar","items":2,"time":"1 min","markedBy":"App"}],"extraPractice":"Each week has 3 extra items. A learner who scores below 60% on steps 3-4 gets them before moving on; a learner who scores 90% or more on steps 3-4 skips step 6.","feedback":"Every item has a one-line reason, shown straight after the answer. Wrong answers become review cards. In steps 6 and 8 the AI accepts any correct answer that uses the target form, not only the key.","itemFormat":"Each item has an id, a step, a target (Main, Light or Review), the prompt, the options where there are any, the key, accepted variants, and the reason.","items":[{"id":"W2-M1","step":"Meaning","target":"Main","prompt":"\"I''m meeting a careers adviser on Tuesday.\" Is this an arrangement already made, or a decision made now?","options":["arrangement","decision now"],"key":"arrangement","accepted":[],"reason":"The present continuous is used for fixed arrangements."},{"id":"W2-M2","step":"Meaning","target":"Main","prompt":"\"When I finish it, I''ll apply.\" Is finishing the course in the present or the future?","options":["present","future"],"key":"future","accepted":[],"reason":"After when, use the present simple for the future."},{"id":"W2-M3","step":"Meaning","target":"Main","prompt":"\"If I had more time, I''d study full-time.\" Does the speaker have more time?","options":["Yes","No"],"key":"No","accepted":[],"reason":"The second conditional describes an imagined situation."},{"id":"W2-C1","step":"Choose","target":"Main","prompt":"Look at those clouds! It ___ rain.","options":["''s going to","''s raining"],"key":"''s going to","accepted":[],"reason":"A prediction based on what you can see now."},{"id":"W2-C2","step":"Choose","target":"Main","prompt":"I ___ lunch with my sister tomorrow. We''ve booked a table.","options":["''m having","have"],"key":"''m having","accepted":[],"reason":"A fixed arrangement."},{"id":"W2-C3","step":"Choose","target":"Main","prompt":"My flight ___ at 6 a.m., so I need to leave home at 4.","options":["leaves","is leave"],"key":"leaves","accepted":[],"reason":"Timetables use the present simple."},{"id":"W2-C4","step":"Choose","target":"Main","prompt":"A: I''ve left my wallet at home. B: Don''t worry, I ___ for the coffees.","options":["''ll pay","pay"],"key":"''ll pay","accepted":[],"reason":"An offer or decision made while speaking."},{"id":"W2-C5","step":"Choose","target":"Main","prompt":"I''ll call you as soon as I ___ home.","options":["get","will get"],"key":"get","accepted":[],"reason":"After as soon as, use the present simple for the future."},{"id":"W2-C6","step":"Choose","target":"Main","prompt":"I ___ start my own business one day. That''s my plan.","options":["''m going to","''m starting"],"key":"''m going to","accepted":[],"reason":"An intention with no fixed arrangement yet."},{"id":"W2-G1","step":"Complete","target":"Main","prompt":"We ___ (move) to Valencia next month. We''ve already signed the contract.","options":[],"key":"''re moving","accepted":["are moving"],"reason":"A fixed arrangement."},{"id":"W2-G2","step":"Complete","target":"Main","prompt":"I''m sure you ___ (enjoy) the course.","options":[],"key":"''ll enjoy","accepted":["will enjoy"],"reason":"A prediction based on opinion."},{"id":"W2-G3","step":"Complete","target":"Main","prompt":"Before I ___ (start) my new job, I''m going to take a holiday.","options":[],"key":"start","accepted":[],"reason":"After before, use the present simple for the future."},{"id":"W2-G4","step":"Complete","target":"Main","prompt":"I ___ (not / come) to the meeting on Friday. I''ve got a dentist''s appointment.","options":[],"key":"''m not coming","accepted":["am not coming"],"reason":"A fixed arrangement."},{"id":"W2-G5","step":"Complete","target":"Main","prompt":"Wait, I ___ (help) you carry that.","options":[],"key":"''ll help","accepted":["will help"],"reason":"An offer made while speaking."},{"id":"W2-F1","step":"Fix","target":"Main","prompt":"I''ll tell you when I will know the results.","options":[],"key":"I''ll tell you when I know the results.","accepted":[],"reason":"After when, use the present simple for the future."},{"id":"W2-F2","step":"Fix","target":"Main","prompt":"I can''t come on Saturday. I will visit my parents. We arranged it last week.","options":[],"key":"I''m visiting my parents.","accepted":[],"reason":"It was arranged, so use the present continuous."},{"id":"W2-F3","step":"Fix","target":"Main","prompt":"We''re go to the cinema tonight.","options":[],"key":"We''re going to the cinema tonight.","accepted":[],"reason":"The present continuous needs the -ing form."},{"id":"W2-R1","step":"Rewrite","target":"Main","prompt":"My plan: find a new flat. (going to)","options":[],"key":"I''m going to find a new flat.","accepted":[],"reason":"An intention."},{"id":"W2-R2","step":"Rewrite","target":"Main","prompt":"Finish work, then phone you. (as soon as)","options":[],"key":"I''ll phone you as soon as I finish work.","accepted":["As soon as I finish work, I''ll phone you."],"reason":"Will in the main clause, present simple after as soon as."},{"id":"W2-R3","step":"Rewrite","target":"Main","prompt":"Meeting with Ana, Thursday 3 p.m., booked. (present continuous)","options":[],"key":"I''m meeting Ana on Thursday at 3 p.m.","accepted":[],"reason":"A fixed arrangement."},{"id":"W2-L1","step":"Light","target":"Light","prompt":"If you heat ice, it ___.","options":["melts","would melt"],"key":"melts","accepted":[],"reason":"Zero conditional: always true."},{"id":"W2-L2","step":"Light","target":"Light","prompt":"If it ___ tomorrow, we''ll stay at home.","options":["rains","will rain"],"key":"rains","accepted":[],"reason":"First conditional: present simple after if."},{"id":"W2-L3","step":"Light","target":"Light","prompt":"If I ___ you, I''d take the job.","options":["were","am"],"key":"were","accepted":["was"],"reason":"Second conditional: an imagined situation."},{"id":"W2-U1","step":"Use it","target":"Main","prompt":"Tell me one plan you have for next month and one thing you''ve already arranged.","options":[],"key":"Correct sentences with going to and the present continuous","accepted":[],"reason":"AI checks the form and gives one correction."},{"id":"W2-U2","step":"Use it","target":"Main","prompt":"What would you do if you had a free year with no work or study?","options":[],"key":"A correct second conditional","accepted":[],"reason":"AI checks the form and gives one correction."},{"id":"W2-V1","step":"Review (Week 1)","target":"Review","prompt":"I ___ in this city since 2021.","options":["''ve lived","lived"],"key":"''ve lived","accepted":[],"reason":"Up to now with since."},{"id":"W2-V2","step":"Review (Week 1)","target":"Review","prompt":"When I was young, I ___ love cartoons.","options":["used to","would"],"key":"used to","accepted":[],"reason":"Love is a state, so would is not possible."},{"id":"W2-E1","step":"Extra","target":"Extra","prompt":"I ___ (see) the doctor at 10 tomorrow. It''s booked.","options":[],"key":"''m seeing","accepted":["am seeing"],"reason":"A fixed arrangement."},{"id":"W2-E2","step":"Extra","target":"Extra","prompt":"I think it ___ (be) sunny at the weekend.","options":[],"key":"''ll be","accepted":["will be"],"reason":"A prediction based on opinion."},{"id":"W2-E3","step":"Extra","target":"Extra","prompt":"Call me after you ___ (land).","options":[],"key":"land","accepted":[],"reason":"After after, use the present simple for the future."}]}},"speaking":{"status":"pilot draft — pending second-teacher review","main":"future forms.","light":"conditionals 0-2 (review).","featured":["goal","intend to","career","look forward to."],"flow":{"shadowingWarmup":"3 min; listen to three short chunks from the model answer at normal and slower speed, repeat each, then compare your recording with the model. Self-check against a short prosody checklist; never scored.","plan":"2 min; read the cue card, note key words if you like; the model answer is hidden.","record":"60-90 s; one recording covering every cue point; AI marked against the descriptors.","feedbackAndRetry":"5 min; a band for each criterion, one strength, one specific correction; then record again, with the model available to compare. AI; a teacher confirms flagged recordings.","conversation":"Any time in the week (recommended); 15 min; 3-4 learner turns with the AI partner, then feedback and one retried turn; AI.","unlocking":"The speaking task counts once the first recording is submitted; the retry is encouraged, not required."},"prompt":"Tell me about a goal you have. What have you already arranged, what will you do when that step is complete, and what will you do if the plan changes?","cueCard":"My goal · Already arranged · When it''s done... · If it doesn''t work out...","phraseBank":["My goal is to...","I intend to...","I''m going to...","I''m meeting / starting... on...","I''m really looking forward to...","When I finish..., I''ll...","As soon as..., I''ll...","If it doesn''t work out, I''ll...","If I had..., I''d..."],"model":"> My goal is to start a career in design. I intend to take a short course this spring, and I''m meeting someone from the college on Thursday. I''m looking forward to seeing some of the students'' work. A friend who did the course has offered to help me choose a project. I think it''ll be hard work, but it''ll be worth it. When I finish the course, I''ll apply for a few junior roles and use my project to show what I can do. If I don''t get a place this spring, I''ll take an evening class instead. And if I had more free time, I''d study full-time, but I need to keep working for now.","onTarget":"covers all four cue points; uses at least two different future forms correctly; uses a first or second conditional; uses two featured items.","correctionPriority":"1) will after when, as soon as or if (when I will finish); 2) going to vs present continuous for arrangements; 3) look forward to + -ing.","shadowingChunks":[{"chunk":"I''m looking forward to seeing their work.","listenFor":"to is weak (\"tuh\"); stress on look, for and see"},{"chunk":"When I finish the course, I''ll apply.","listenFor":"the short I''ll; a small pause after course"},{"chunk":"If I had more free time, I''d study full-time.","listenFor":"the short I''d; rising tone after time, falling at the end"}],"conversation":{"title":"a colleague asks about plans","turns":[{"partner":"So, any plans for the next few months?","learner":"Give a goal (going to, intend to)","followUp":"Oh nice. Why that?"},{"partner":"That sounds great. Have you arranged anything yet?","learner":"Describe an arrangement (present continuous)","followUp":"When is that happening?"},{"partner":"And what happens after that?","learner":"Say the next step (when / as soon as + will)","followUp":"What will you do first?"},{"partner":"What if it doesn''t work out?","learner":"Give a back-up plan (first conditional)","followUp":"And if you could do anything at all? (second conditional)"}],"closingLine":"Good luck with it. Let me know how Thursday goes!","naturalRecastExample":"learner \"When I will finish, I start looking for work.\" Partner: \"Ah, so when you finish, you''ll start looking for work?\""},"delayedRecall":"You''ve decided to learn a new skill. What have you arranged, what will you do afterwards, and what will you do if it doesn''t work out?","b2Stretch":"explain why the goal matters and weigh two alternatives, without the cue card."},"writing":{"status":"pilot draft — pending second-teacher review","title":"A goal and a plan","durationMinutes":30,"words":[120,150],"prompt":"Write a letter to the Ask Sam advice column about a goal. Include a confirmed arrangement, your next step, a back-up plan and one question asking for advice. Use in order to once to explain a purpose.","grammar":"going to; present continuous for arrangements; will; present simple after when / as soon as; first and second conditionals","featuredWords":["goal","intend to","career","look forward to"],"stretchWords":[],"linkers":["in order to"],"readerAndPurpose":"A letter to an advice column, like Daniel’s letter in this week’s reading. The aim is to explain your situation and plans clearly, then ask one clear question.","requiredPoints":["The goal","One arrangement that is already fixed (day or date)","The next step after that (when / as soon as + will)","A back-up plan (if + present simple, will)","One question asking for advice (Should I...?)","in order to used once"],"planFrame":["Greeting, who you are and the goal","What is already arranged","The next step and the back-up plan","Your worry, one question for Sam, and a close"],"usefulLanguage":["My goal is to...","I intend to...","I’m going to... in order to...","I’m meeting / starting... on...","When I finish..., I’ll...","If I don’t..., I’ll...","I’m looking forward to..., but I’m worried about...","Should I...?","Thanks,"],"onTarget":"covers every required point; uses at least two future forms correctly; uses a first or second conditional; uses two featured items; ends with one clear question for Sam; has a greeting and close that suit an advice column.","correctionPriority":"1) will after when, as soon as or if (when I will finish); 2) going to vs present continuous for fixed arrangements; 3) look forward to + -ing.","reviseAndRetryFocus":"Check every time clause (when, as soon as, before, after) uses the present simple, and add a day or date to the arrangement.","modelAnswer":"Dear Sam,\n\nI’m 31 and I work in a bank, but my goal is to start a career in graphic design. I’ve signed up for an online course, which starts on 10 January, and I’m meeting my tutor for the first time next Monday.\n\nI’m going to practise every evening in order to build a portfolio quickly. When I finish the course in June, I’ll apply for junior jobs in design studios. If I don’t find a job straight away, I’ll do some freelance work to get more experience.\n\nI intend to keep my current job until then. I’m really looking forward to the course, but I’m worried about telling my manager. Should I tell her about my plans now, or wait until I find a new job?\n\nThanks,\nLucía","delayedRecall":"You''ve decided to learn a new skill. What have you arranged, what will you do afterwards, and what will you do if it doesn''t work out?","pairedReading":"\"Ask Sam\" (advice column)"},"conversation":{"scenario":"A colleague asks about plans.","openingLine":"So, any plans for the next few months?","learnerMoves":"Give a goal, an arrangement and a next step; say what they''ll do if it doesn''t work out.","targetLanguage":"Future forms, first and second conditionals; goal, intend to, career, look forward to"},"vocabulary":{"core":[{"target":"ambition","type":"n.","cefr":"B1","use":"P","example":"Her ambition is to run her own restaurant."},{"target":"goal","type":"n.","cefr":"B1","use":"P","example":"My goal is to start a career in design."},{"target":"achieve","type":"v.","cefr":"B1","use":"P","example":"If you practise regularly, you''ll achieve your goal."},{"target":"intend","type":"v.","cefr":"B1","use":"P","example":"We intend to move to the coast next year."},{"target":"career","type":"n.","cefr":"B1","use":"P","example":"She''s going to start a career in engineering."},{"target":"deadline","type":"n.","cefr":"B2","use":"B","example":"The deadline for applications is 30 April."},{"target":"apply","type":"v.","cefr":"B1","use":"P","example":"She''s going to apply for a job at the museum."},{"target":"look forward to","type":"mw. v.","cefr":"B1","use":"P","example":"I''m looking forward to starting my new course."},{"target":"determined","type":"adj.","cefr":"B1","use":"B","example":"He''s determined to pass, so he''s going to practise every day."}],"collocations":[{"target":"work towards","example":"I''m working towards a degree in nursing."},{"target":"take the first step","example":"I''ll take the first step and contact the college."},{"target":"improve your skills","example":"This course will help you improve your skills."},{"target":"put (something) off","example":"Don''t put off booking the course. With a pronoun: put it off."},{"target":"set a goal","example":"I''m going to set myself a goal of reading one book a month."},{"target":"meet a deadline","example":"We''ll need to finish on Thursday to meet Friday''s deadline."}],"families":[{"base":"ambition","forms":["ambitious"],"card":"ambitious on ambition; achievable recognition on achieve"},{"base":"achieve","forms":["achievement","achievable"],"card":"achievement on achieve; achievable recognition only"},{"base":"success","forms":["succeed","success","successful","successfully"],"card":"one shared family card; successfully guided B2"}],"optional":[],"newCards":16,"note":"Separate apply for a job from apply to an organisation. In look forward to, to is a preposition: use a noun or an -ing form. No future continuous (Week 14)."},"linkers":[{"target":"in order to","cefr":"B1","function":"purpose","taughtIn":"writing task","example":"In order to save money, I''ll cook at home."}],"checkpoint1":{"mainItems":4,"lightItems":1,"focus":"Intention, arrangement, two ordinary future time clauses; Light: first vs second conditional"}},{"number":3,"title":"Agree on house rules","canDo":"Say what is required, forbidden, optional or possible, ask and give permission, and offer advice.","featuredVocabulary":["get on with","arrange","routine","politely"],"stretchPhrases":[],"grammar":{"main":"modals of obligation, advice, ability, permission.","light":"question forms; basic linkers.","sampleItems":[],"authoringNote":"For a specific past success use was able to or managed to, not could; couldn''t works for a specific failure. Keep this contrast as a B2 note, not a scored item.","practice":{"status":"pilot draft — pending second-teacher review","durationMinutes":20,"notice":{"text":"Welcome to the flat! A few things: we have to put the bins out on Thursdays, and you mustn''t smoke inside. You don''t have to join us for dinner, but you''re always welcome. You can use the washing machine until 10 p.m. If anything breaks, you should ask Tom. He can fix almost anything! Could you tell me when you''re arriving? Apart from that, just make yourself at home.","targetForms":"eight","markedBy":"App"},"steps":[{"step":1,"exercise":"Notice: listen to and read a short text, tap the target forms","items":"1 text","time":"2 min","markedBy":"App"},{"step":2,"exercise":"Check the meaning: short questions about what the form means","items":3,"time":"2 min","markedBy":"App"},{"step":3,"exercise":"Choose in context: two options","items":6,"time":"3 min","markedBy":"App"},{"step":4,"exercise":"Complete: verb or prompt in brackets","items":5,"time":"3 min","markedBy":"App"},{"step":5,"exercise":"Find and fix the mistake","items":3,"time":"2 min","markedBy":"App"},{"step":6,"exercise":"Rewrite with the target form","items":3,"time":"2 min","markedBy":"App, with AI checking other correct answers"},{"step":7,"exercise":"Light point: choose or reorder","items":3,"time":"2 min","markedBy":"App"},{"step":8,"exercise":"Use it yourself: two sentences about your own life, spoken or typed","items":2,"time":"3 min","markedBy":"AI, instant feedback and one retry"},{"step":9,"exercise":"Spaced review: earlier grammar","items":2,"time":"1 min","markedBy":"App"}],"extraPractice":"Each week has 3 extra items. A learner who scores below 60% on steps 3-4 gets them before moving on; a learner who scores 90% or more on steps 3-4 skips step 6.","feedback":"Every item has a one-line reason, shown straight after the answer. Wrong answers become review cards. In steps 6 and 8 the AI accepts any correct answer that uses the target form, not only the key.","itemFormat":"Each item has an id, a step, a target (Main, Light or Review), the prompt, the options where there are any, the key, accepted variants, and the reason.","items":[{"id":"W3-M1","step":"Meaning","target":"Main","prompt":"\"You don''t have to join us for dinner.\" Is dinner required, optional or not allowed?","options":["required","optional","not allowed"],"key":"optional","accepted":[],"reason":"Don''t have to means it isn''t necessary."},{"id":"W3-M2","step":"Meaning","target":"Main","prompt":"\"You mustn''t smoke inside.\" Is smoking inside optional or not allowed?","options":["optional","not allowed"],"key":"not allowed","accepted":[],"reason":"Mustn''t means it is forbidden."},{"id":"W3-M3","step":"Meaning","target":"Main","prompt":"\"He can fix almost anything.\" Is this about ability or permission?","options":["ability","permission"],"key":"ability","accepted":[],"reason":"Here can describes what Tom is able to do."},{"id":"W3-C1","step":"Choose","target":"Main","prompt":"You ___ wear a seatbelt in a car. It''s the law.","options":["have to","should"],"key":"have to","accepted":[],"reason":"A rule, not just advice."},{"id":"W3-C2","step":"Choose","target":"Main","prompt":"It''s a free museum, so you ___ pay.","options":["don''t have to","mustn''t"],"key":"don''t have to","accepted":[],"reason":"Paying isn''t necessary, but it isn''t forbidden."},{"id":"W3-C3","step":"Choose","target":"Main","prompt":"You look tired. You ___ go to bed early.","options":["should","have to"],"key":"should","accepted":[],"reason":"Advice, not a rule."},{"id":"W3-C4","step":"Choose","target":"Main","prompt":"___ I use your phone? Mine''s dead.","options":["Could","Must"],"key":"Could","accepted":[],"reason":"Asking for permission."},{"id":"W3-C5","step":"Choose","target":"Main","prompt":"When I was ten, I ___ swim very well.","options":["could","can"],"key":"could","accepted":[],"reason":"General ability in the past."},{"id":"W3-C6","step":"Choose","target":"Main","prompt":"Passengers ___ use their phones during take-off.","options":["mustn''t","don''t have to"],"key":"mustn''t","accepted":[],"reason":"It is forbidden."},{"id":"W3-G1","step":"Complete","target":"Main","prompt":"I ___ (have to / work) late tomorrow, so I can''t come.","options":[],"key":"have to work","accepted":[],"reason":"A requirement."},{"id":"W3-G2","step":"Complete","target":"Main","prompt":"You ___ (not / have to / bring) anything. We''ve got plenty of food.","options":[],"key":"don''t have to bring","accepted":[],"reason":"Not necessary."},{"id":"W3-G3","step":"Complete","target":"Main","prompt":"Sorry, I ___ (can / not / hear) you. Can you speak up?","options":[],"key":"can''t hear","accepted":["cannot hear"],"reason":"Ability, negative."},{"id":"W3-G4","step":"Complete","target":"Main","prompt":"I think you ___ (should / talk) to your manager about it.","options":[],"key":"should talk","accepted":[],"reason":"Advice."},{"id":"W3-G5","step":"Complete","target":"Main","prompt":"___ I ___ (can / borrow) your charger?","options":[],"key":"Can I borrow","accepted":[],"reason":"A permission question: can before the subject."},{"id":"W3-F1","step":"Fix","target":"Main","prompt":"You must to show your ticket.","options":[],"key":"You must show your ticket.","accepted":[],"reason":"Modals are followed by the verb without to."},{"id":"W3-F2","step":"Fix","target":"Main","prompt":"She can speaks three languages.","options":[],"key":"She can speak three languages.","accepted":[],"reason":"No -s after a modal."},{"id":"W3-F3","step":"Fix","target":"Main","prompt":"Do I can leave early today?","options":[],"key":"Can I leave early today?","accepted":[],"reason":"Modals make questions without do."},{"id":"W3-R1","step":"Rewrite","target":"Main","prompt":"It isn''t necessary to book a table. (don''t have to)","options":[],"key":"You don''t have to book a table.","accepted":["We don''t have to book a table."],"reason":"Not necessary."},{"id":"W3-R2","step":"Rewrite","target":"Main","prompt":"Smoking is not allowed here. (mustn''t)","options":[],"key":"You mustn''t smoke here.","accepted":[],"reason":"Forbidden."},{"id":"W3-R3","step":"Rewrite","target":"Main","prompt":"Is it OK if I sit here? (Could)","options":[],"key":"Could I sit here?","accepted":[],"reason":"A polite permission question."},{"id":"W3-L1","step":"Light","target":"Light","prompt":"Put the words in order: What time / you / usually / do / get home?","options":[],"key":"What time do you usually get home?","accepted":[],"reason":"Auxiliary before the subject in questions."},{"id":"W3-L2","step":"Light","target":"Light","prompt":"___ the bins out on Thursdays?","options":["Who takes","Who does take"],"key":"Who takes","accepted":[],"reason":"Who is the subject, so no do."},{"id":"W3-L3","step":"Light","target":"Light","prompt":"The flat is small. ___, it''s very close to the station.","options":["On the other hand","Apart from that"],"key":"On the other hand","accepted":[],"reason":"It introduces a contrasting point."},{"id":"W3-U1","step":"Use it","target":"Main","prompt":"Tell a new flatmate one thing they have to do, one thing they mustn''t do and one thing they don''t have to do.","options":[],"key":"Correct sentences with have to, mustn''t and don''t have to","accepted":[],"reason":"AI checks the form and gives one correction."},{"id":"W3-U2","step":"Use it","target":"Main","prompt":"Ask your new flatmate two questions about their routine.","options":[],"key":"Two correctly formed questions","accepted":[],"reason":"AI checks word order and gives one correction."},{"id":"W3-V1","step":"Review (Week 2)","target":"Review","prompt":"I''ll text you when I ___ at the station.","options":["arrive","will arrive"],"key":"arrive","accepted":[],"reason":"After when, use the present simple for the future."},{"id":"W3-V2","step":"Review (Week 1)","target":"Review","prompt":"By the time we got there, the shop ___.","options":["had closed","has closed"],"key":"had closed","accepted":[],"reason":"It closed before we arrived."},{"id":"W3-E1","step":"Extra","target":"Extra","prompt":"Students ___ (not / have to) wear a uniform at this school.","options":[],"key":"don''t have to","accepted":[],"reason":"It isn''t required."},{"id":"W3-E2","step":"Extra","target":"Extra","prompt":"You ___ (mustn''t / touch) the paintings.","options":[],"key":"mustn''t touch","accepted":[],"reason":"It is forbidden."},{"id":"W3-E3","step":"Extra","target":"Extra","prompt":"___ I ___ (could / ask) you a question?","options":[],"key":"Could I ask","accepted":[],"reason":"A polite permission question."}]}},"speaking":{"status":"pilot draft — pending second-teacher review","main":"modals of obligation, advice, ability, permission.","light":"question forms; basic linkers.","featured":["get on with","arrange","routine","politely."],"flow":{"shadowingWarmup":"3 min; listen to three short chunks from the model answer at normal and slower speed, repeat each, then compare your recording with the model. Self-check against a short prosody checklist; never scored.","plan":"2 min; read the cue card, note key words if you like; the model answer is hidden.","record":"60-90 s; one recording covering every cue point; AI marked against the descriptors.","feedbackAndRetry":"5 min; a band for each criterion, one strength, one specific correction; then record again, with the model available to compare. AI; a teacher confirms flagged recordings.","conversation":"Any time in the week (recommended); 15 min; 3-4 learner turns with the AI partner, then feedback and one retried turn; AI.","unlocking":"The speaking task counts once the first recording is submitted; the retry is encouraged, not required."},"prompt":"A new flatmate arrives tomorrow. Record a welcome: explain one shared responsibility, one rule and one optional routine, give one piece of advice, and end with a question for them.","cueCard":"A shared job · A rule · Something optional · Advice · A question for them","phraseBank":["We have to...","You mustn''t...","You don''t have to..., but...","You can... until...","You should...","If you need..., just ask politely","Apart from that,...","What time do you usually...?","Could you tell me...?"],"model":"> Welcome to the flat! There are a few things you need to know. We have to clean up after cooking, and we mustn''t leave the cooker on when we go out. You don''t have to cook for everyone, but we usually eat together on Fridays. You can use the washing machine until ten. The neighbours can hear it through the wall, so if you need it later, please ask them politely first. I couldn''t cook at all when I moved in, so don''t worry if you''re still learning. I think we should arrange a cleaning rota around our work hours. Apart from that, there''s no fixed routine. We all get on with each other really well, so if you''re not sure about something, just ask. What time do you usually get home, by the way?","onTarget":"covers all five cue points; uses have to, mustn''t and don''t have to correctly at least once between them; gives advice with should; ends with a correctly formed question; uses two featured items.","correctionPriority":"1) mustn''t vs don''t have to; 2) to after a modal (must to); 3) question word order.","shadowingChunks":[{"chunk":"You don''t have to cook for everyone.","listenFor":"stress on don''t and cook; to is weak (\"tuh\")"},{"chunk":"We mustn''t leave the cooker on.","listenFor":"the first t in mustn''t is silent (\"mussnt\")"},{"chunk":"What time do you usually get home?","listenFor":"do you runs together (\"dyuh\"); the voice falls at the end"}],"conversation":{"title":"a new flatmate''s first evening","turns":[{"partner":"Hi! Is there anything I need to know about the kitchen?","learner":"Explain a rule or a shared job (have to, mustn''t)","followUp":"Anything else, like the bins?"},{"partner":"I sometimes work late. Could I use the washing machine tonight?","learner":"Answer the permission request with a reason (can, can''t, can hear)","followUp":"Is there a time when it''s a problem?"},{"partner":"Great. Is there anything I don''t need to worry about?","learner":"Mention something optional (don''t have to; apart from that)","followUp":"What about cooking?"},{"partner":"Do you want to ask me anything?","learner":"Ask a correctly formed question about their routine","followUp":"(answers, e.g. \"About nine, most days\") So how should we organise the cleaning?"}],"closingLine":"Thanks, that''s really helpful. I think I''m going to like it here!","naturalRecastExample":"learner \"You must to clean the kitchen.\" Partner: \"Right, so I must clean the kitchen after cooking. No problem.\""},"delayedRecall":"Tell a new colleague one thing they need to do, one thing they mustn''t do and one thing that''s optional.","b2Stretch":"add a likely problem (noise, guests or bills) and suggest a compromise, without the cue card."},"writing":{"status":"pilot draft — pending second-teacher review","title":"Welcome to the flat","durationMinutes":30,"words":[120,150],"prompt":"Write a welcome message for a new flatmate. Include one requirement, one rule, one optional thing and one piece of advice. Use at least one of the week’s linkers: on the other hand, in fact, apart from that.","grammar":"have to, mustn’t, don’t have to, should, can / could; questions","featuredWords":["get on with","arrange","routine","politely"],"stretchWords":[],"linkers":["on the other hand","in fact","apart from that (required)"],"readerAndPurpose":"A friendly welcome email to someone moving in. The aim is to explain how the flat works without sounding strict.","requiredPoints":["One requirement (have to)","One rule (mustn’t)","One optional thing (don’t have to)","One piece of advice (should)","At least one of the week’s linkers"],"planFrame":["Welcome and when they arrive","Requirements and rules","What’s optional, and advice","Friendly close, or a question for them"],"usefulLanguage":["Welcome to the flat!","We have to...","You mustn’t... because...","You don’t have to..., but...","You should...","On the other hand,...","In fact,...","Apart from that,...","We all get on with each other...","See you on...!"],"onTarget":"covers every required point; uses have to, mustn’t and don’t have to correctly between them; gives advice with should; uses one of the week’s linkers; uses two featured items.","correctionPriority":"1) mustn’t vs don’t have to; 2) to after a modal (you must to); 3) -s after a modal (she can speaks).","reviseAndRetryFocus":"Check that each rule uses the right modal for its meaning (required, forbidden, optional), and add a linker where two ideas contrast.","modelAnswer":"Hi Tom,\n\nWelcome to the flat! We’re really pleased you’re moving in on Saturday. Here are a few things you should know.\n\nWe have to take the bins out on Thursday evenings, and we take turns, so check the rota on the kitchen door. You mustn’t leave food in the living room, because we’ve had problems with mice! On the other hand, you don’t have to join us for dinner. We all have different routines, and most of us cook for ourselves.\n\nMy advice? You should get to know our neighbour, Mrs Hill. In fact, she’s lived here for forty years and knows everything about the area. Apart from that, just relax and make yourself at home. We all get on with each other really well.\n\nSee you on Saturday!\nElena","delayedRecall":"Tell a new colleague one thing they need to do, one thing they mustn''t do and one thing that''s optional.","pairedReading":"\"Welcome to 14 Park Road!\" (email)"},"conversation":{"scenario":"A new flatmate''s first evening.","openingLine":"Hi! Is there anything I need to know about the kitchen?","learnerMoves":"Explain a rule, answer a permission request (''Could I use the washing machine tonight?''), ask one question, suggest an arrangement.","targetLanguage":"Obligation, ability and permission modals, question forms, linkers; get on with, arrange, routine, politely"},"vocabulary":{"core":[{"target":"get on with","type":"mw. v.","cefr":"B1","use":"P","example":"You don''t have to be close friends to get on with your colleagues."},{"target":"catch up (with)","type":"phr. v.","cefr":"B2","use":"B","example":"Can we meet after work and catch up? Here: exchange news."},{"target":"arrange","type":"v.","cefr":"B1","use":"P","example":"We should arrange to meet outside the station."},{"target":"routine","type":"n.","cefr":"B1","use":"P","example":"Try to stick to a routine during busy weeks."},{"target":"rely on","type":"mw. v.","cefr":"B2","use":"B","example":"You can rely on Maria to help if there''s a problem."},{"target":"misunderstanding","type":"n.","cefr":"B2","use":"B","example":"We should talk and clear up the misunderstanding."},{"target":"invite (someone) round","type":"phr. v.","cefr":"B1*","use":"P","example":"Can I invite some friends round on Saturday? BrE."},{"target":"awkward (situation)","type":"adj.","cefr":"B2","use":"B","example":"It was an awkward situation, but we managed to talk it through."},{"target":"politely","type":"adv.","cefr":"B1","use":"P","example":"You can disagree politely."}],"collocations":[{"target":"make an effort","example":"We should make an effort to welcome new colleagues."},{"target":"have a lot in common","example":"We have a lot in common: we both love cycling."},{"target":"get in touch","example":"You should get in touch with the organiser."},{"target":"come over","example":"Can you come over for coffee on Saturday?"},{"target":"keep a promise","example":"You should keep a promise even if it''s difficult."}],"families":[{"base":"friend","forms":["unfriendly","friendship"],"card":"shared family card"},{"base":"politely","forms":["politeness","impolite"],"card":"recognition only on politely"},{"base":"rely on","forms":["reliable","unreliable","reliably"],"card":"reliable and unreliable on rely on; reliably recognition only"}],"optional":[{"target":"pop round","example":"Can I pop round after work? Informal BrE; short visit."}],"newCards":15,"note":"Pair get on with (relationship), catch up with (exchange news) and get in touch with (initiate contact). Week 3 linkers are the Light grammar point and required in the welcome-message writing task."},"linkers":[{"target":"on the other hand","cefr":"B1","function":"contrast","taughtIn":"grammar task","example":"Living with friends can be fun. On the other hand, you have to share the housework."},{"target":"in fact","cefr":"B1","function":"emphasis","taughtIn":"grammar task","example":"We get on really well. In fact, we talk almost every day."},{"target":"apart from that","cefr":"B1*","function":"exception","taughtIn":"grammar task","example":"The bus was late. Apart from that, the day went well."}],"checkpoint1":{"mainItems":4,"lightItems":1,"focus":"One item each for obligation, advice, ability and permission; Light: one question form"}},{"number":4,"title":"Give a short visitor guide","canDo":"Describe customs and past facts with the passive, identify places and compare them.","featuredVocabulary":["local","custom","destination","tradition","set off"],"stretchPhrases":[],"grammar":{"main":"passive voice (present and past simple).","light":"relative clauses; comparatives and superlatives.","sampleItems":[],"authoringNote":"Use a guide-card cue such as ''Market hall / build / 1890'' in controlled practice. In free speech accept natural active wording; don''t require a set number of passives.","practice":{"status":"pilot draft — pending second-teacher review","durationMinutes":20,"notice":{"text":"Toledo is one of the oldest cities in Spain. Work on its cathedral was started in 1226, and today the city is visited by thousands of tourists every year. Marzipan is made in local convents and bakeries, and it is sold in shops all over the old town. The best time to go is spring, when it''s quieter than in summer. There''s a viewpoint where you can see the whole city.","targetForms":"eight","markedBy":"App"},"steps":[{"step":1,"exercise":"Notice: listen to and read a short text, tap the target forms","items":"1 text","time":"2 min","markedBy":"App"},{"step":2,"exercise":"Check the meaning: short questions about what the form means","items":3,"time":"2 min","markedBy":"App"},{"step":3,"exercise":"Choose in context: two options","items":6,"time":"3 min","markedBy":"App"},{"step":4,"exercise":"Complete: verb or prompt in brackets","items":5,"time":"3 min","markedBy":"App"},{"step":5,"exercise":"Find and fix the mistake","items":3,"time":"2 min","markedBy":"App"},{"step":6,"exercise":"Rewrite with the target form","items":3,"time":"2 min","markedBy":"App, with AI checking other correct answers"},{"step":7,"exercise":"Light point: choose or reorder","items":3,"time":"2 min","markedBy":"App"},{"step":8,"exercise":"Use it yourself: two sentences about your own life, spoken or typed","items":2,"time":"3 min","markedBy":"AI, instant feedback and one retry"},{"step":9,"exercise":"Spaced review: earlier grammar","items":2,"time":"1 min","markedBy":"App"}],"extraPractice":"Each week has 3 extra items. A learner who scores below 60% on steps 3-4 gets them before moving on; a learner who scores 90% or more on steps 3-4 skips step 6.","feedback":"Every item has a one-line reason, shown straight after the answer. Wrong answers become review cards. In steps 6 and 8 the AI accepts any correct answer that uses the target form, not only the key.","itemFormat":"Each item has an id, a step, a target (Main, Light or Review), the prompt, the options where there are any, the key, accepted variants, and the reason.","items":[{"id":"W4-M1","step":"Meaning","target":"Main","prompt":"\"Marzipan is made in local convents and bakeries.\" What is the sentence mainly about?","options":["the marzipan","the people who make it"],"key":"the marzipan","accepted":[],"reason":"The passive puts the focus on the thing, not the person doing the action."},{"id":"W4-M2","step":"Meaning","target":"Main","prompt":"\"Work on its cathedral was started in 1226.\" Present or past?","options":["present","past"],"key":"past","accepted":[],"reason":"Was + past participle is the past simple passive."},{"id":"W4-M3","step":"Meaning","target":"Main","prompt":"\"There''s a viewpoint where you can see the whole city.\" What does where refer to?","options":["the city","the viewpoint"],"key":"the viewpoint","accepted":[],"reason":"Where introduces information about a place."},{"id":"W4-C1","step":"Choose","target":"Main","prompt":"English ___ in many countries.","options":["is spoken","speaks"],"key":"is spoken","accepted":[],"reason":"The language is the focus; people speak it."},{"id":"W4-C2","step":"Choose","target":"Main","prompt":"This bridge ___ in 1890.","options":["was built","is built"],"key":"was built","accepted":[],"reason":"Past time, passive."},{"id":"W4-C3","step":"Choose","target":"Main","prompt":"The rooms ___ every morning.","options":["are cleaned","are cleaning"],"key":"are cleaned","accepted":[],"reason":"Rooms don''t clean; someone cleans them."},{"id":"W4-C4","step":"Choose","target":"Main","prompt":"The thieves ___ by the police yesterday.","options":["were caught","caught"],"key":"were caught","accepted":[],"reason":"The police did the action; the thieves received it."},{"id":"W4-C5","step":"Choose","target":"Main","prompt":"My bike ___ last night!","options":["was stolen","stole"],"key":"was stolen","accepted":[],"reason":"Someone stole it; we don''t know who."},{"id":"W4-C6","step":"Choose","target":"Main","prompt":"Paella ___ in the pan it is cooked in.","options":["is usually served","usually serves"],"key":"is usually served","accepted":[],"reason":"Someone serves the paella."},{"id":"W4-G1","step":"Complete","target":"Main","prompt":"The festival ___ (hold) every August.","options":[],"key":"is held","accepted":[],"reason":"Present passive; hold, held, held."},{"id":"W4-G2","step":"Complete","target":"Main","prompt":"The letters ___ (deliver) yesterday afternoon.","options":[],"key":"were delivered","accepted":[],"reason":"Past passive, plural subject."},{"id":"W4-G3","step":"Complete","target":"Main","prompt":"These photos ___ (take) by my grandfather in 1975.","options":[],"key":"were taken","accepted":[],"reason":"Past passive; take, took, taken."},{"id":"W4-G4","step":"Complete","target":"Main","prompt":"Breakfast ___ (not / include) in the price.","options":[],"key":"isn''t included","accepted":["is not included"],"reason":"Present passive, negative."},{"id":"W4-G5","step":"Complete","target":"Main","prompt":"Where ___ your car ___ (make)?","options":[],"key":["was","made"],"accepted":[[],[]],"reason":"Past passive question."},{"id":"W4-F1","step":"Fix","target":"Main","prompt":"The museum was build in 1920.","options":[],"key":"The museum was built in 1920.","accepted":[],"reason":"The passive needs the past participle."},{"id":"W4-F2","step":"Fix","target":"Main","prompt":"The windows are clean every week.","options":[],"key":"The windows are cleaned every week.","accepted":[],"reason":"Someone cleans them: use the past participle."},{"id":"W4-F3","step":"Fix","target":"Main","prompt":"The castle visited by thousands of tourists every year.","options":[],"key":"The castle is visited by thousands of tourists every year.","accepted":[],"reason":"The passive needs be."},{"id":"W4-R1","step":"Rewrite","target":"Main","prompt":"They built the castle in the 12th century. (passive)","options":[],"key":"The castle was built in the 12th century.","accepted":[],"reason":"The castle is the focus."},{"id":"W4-R2","step":"Rewrite","target":"Main","prompt":"People grow oranges in this region. (passive)","options":[],"key":"Oranges are grown in this region.","accepted":[],"reason":"\"People\" adds nothing, so leave it out."},{"id":"W4-R3","step":"Rewrite","target":"Main","prompt":"Someone stole my wallet on the train. (passive)","options":[],"key":"My wallet was stolen on the train.","accepted":[],"reason":"We don''t know who did it."},{"id":"W4-L1","step":"Light","target":"Light","prompt":"That''s the restaurant ___ we had our first date.","options":["where","which"],"key":"where","accepted":[],"reason":"Where for a place followed by a full clause."},{"id":"W4-L2","step":"Light","target":"Light","prompt":"The woman ___ lives next door is a doctor.","options":["who","which"],"key":"who","accepted":["that"],"reason":"Who for people."},{"id":"W4-L3","step":"Light","target":"Light","prompt":"The old town is ___ the new town.","options":["more beautiful than","the most beautiful"],"key":"more beautiful than","accepted":[],"reason":"Comparing two places."},{"id":"W4-U1","step":"Use it","target":"Main","prompt":"Describe a famous building or place in your town: when was it built, and what happens there now?","options":[],"key":"Correct present and past passive sentences","accepted":[],"reason":"AI checks the form and gives one correction."},{"id":"W4-U2","step":"Use it","target":"Main","prompt":"Compare your town with another place you know. Which do you like best?","options":[],"key":"A correct comparative and superlative","accepted":[],"reason":"AI checks the form and gives one correction."},{"id":"W4-V1","step":"Review (Week 3)","target":"Review","prompt":"You ___ pay for the museum on Sundays. It''s free.","options":["don''t have to","mustn''t"],"key":"don''t have to","accepted":[],"reason":"Not necessary, but not forbidden."},{"id":"W4-V2","step":"Review (Week 2)","target":"Review","prompt":"If I ___ more money, I''d travel more.","options":["had","have"],"key":"had","accepted":[],"reason":"Second conditional."},{"id":"W4-E1","step":"Extra","target":"Extra","prompt":"Coffee ___ (grow) in Colombia.","options":[],"key":"is grown","accepted":[],"reason":"Present passive for a general fact."},{"id":"W4-E2","step":"Extra","target":"Extra","prompt":"The film ___ (direct) by a young Spanish director.","options":[],"key":"was directed","accepted":[],"reason":"Past passive with by."},{"id":"W4-E3","step":"Extra","target":"Extra","prompt":"The old station ___ (turn) into a museum in 2005.","options":[],"key":"was turned","accepted":[],"reason":"Past passive."}]}},"speaking":{"status":"pilot draft — pending second-teacher review","main":"passive voice (present and past simple).","light":"relative clauses; comparatives and superlatives.","featured":["local","custom","destination","tradition","set off."],"flow":{"shadowingWarmup":"3 min; listen to three short chunks from the model answer at normal and slower speed, repeat each, then compare your recording with the model. Self-check against a short prosody checklist; never scored.","plan":"2 min; read the cue card, note key words if you like; the model answer is hidden.","record":"60-90 s; one recording covering every cue point; AI marked against the descriptors.","feedbackAndRetry":"5 min; a band for each criterion, one strength, one specific correction; then record again, with the model available to compare. AI; a teacher confirms flagged recordings.","conversation":"Any time in the week (recommended); 15 min; 3-4 learner turns with the AI partner, then feedback and one retried turn; AI.","unlocking":"The speaking task counts once the first recording is submitted; the retry is encouraged, not required."},"prompt":"Record a short guide for someone visiting your town for the first time. Include a regular event or custom, one fact about the past, one comparison, and a recommendation.","cueCard":"An event or custom · A fact about the past · A comparison · My recommendation","phraseBank":["It was built in...","... is held every...","It''s a local tradition / custom to...","It''s one of the ...est places in...","It''s quieter / busier than...","There''s a place where...","If you visit, I''d recommend...","I''d set off early to..."],"model":"> If you visit this town, start at the market hall. It was built in 1890, and the food market is held there every Saturday. It''s a local tradition, and you can try food from nearby farms. It''s the busiest place in town on a Saturday morning, so I''d set off early. There''s also a local custom that surprises visitors: most shops are closed on Wednesday afternoons, so plan your shopping for another day. Afterwards, take a walk by the river. It''s quieter than the centre, and it''s the spot where I go to relax. The town isn''t a famous destination, but it''s one of the friendliest places I know.","onTarget":"covers all four cue points; uses at least one present passive and one past passive correctly; uses a comparative or superlative; uses two featured items. Do not require a set number of passives.","correctionPriority":"1) be + past participle (was build, is visit); 2) irregular participles (held, built, taken); 3) comparative forms (more quiet, the most big).","shadowingChunks":[{"chunk":"It was built in eighteen ninety.","listenFor":"was is weak (\"wuz\"); built_in links together"},{"chunk":"It''s the busiest place in town.","listenFor":"stress on BUS-iest and town"},{"chunk":"It''s quieter than the centre.","listenFor":"than is weak (\"thun\"); stress on qui- and cen-"}],"conversation":{"title":"a weekend visitor asks for tips","turns":[{"partner":"I''m here for the weekend. What should I see?","learner":"Recommend a place (relative clause: a place where...)","followUp":"What''s special about it?"},{"partner":"Sounds interesting! Is it old?","learner":"Give a fact about the past (past passive)","followUp":"Do you know when it was built?"},{"partner":"Is it better than the beach?","learner":"Compare two places (comparative or superlative)","followUp":"Which is the best place for a quiet walk?"},{"partner":"Is there anything I should know about local customs?","learner":"Describe a custom or event (present passive; custom, tradition)","followUp":"Is there a festival or market?"}],"closingLine":"Perfect, thanks! I''ll set off early on Saturday, then.","naturalRecastExample":"learner \"It was build in the 1800s.\" Partner: \"Oh, it was built in the 1800s? I''d love to see it.\""},"delayedRecall":"Introduce a venue in your neighbourhood. Say what normally takes place there, give one fact about its past and compare it with another place.","b2Stretch":"add extra information with a non-defining clause (\"The market hall, which was built in 1890, ...\"), without the cue card."},"writing":{"status":"pilot draft — pending second-teacher review","title":"A trip worth taking","durationMinutes":30,"words":[120,150],"prompt":"Write a visitor recommendation or trip note about a place you have been to. Separate facts about the place from what you personally did, and organise it with to begin with and all in all.","grammar":"present and past passive; relative clauses (which, where); comparatives and superlatives","featuredWords":["local","custom","destination","tradition","set off"],"stretchWords":[],"linkers":["to begin with","all in all"],"readerAndPurpose":"A short article or note for someone planning a visit. The aim is to inform (facts) and recommend (your experience).","requiredPoints":["At least one fact about the place in the passive (was built, is held)","What you personally did","A comparison or superlative","A recommendation","to begin with and all in all"],"planFrame":["Where you went and a first opinion","To begin with: the first place, with a fact","What else you did and a comparison","All in all: recommendation and one tip"],"usefulLanguage":["Last month I spent... in...","To begin with, we visited...","It was built in... / ... is held every...","..., which was...,","a place where...","It’s quieter / busier than...","It’s one of the most...","All in all,...","If you go, set off early..."],"onTarget":"covers every required point; uses at least one present or past passive correctly; uses a comparative or superlative; uses to begin with and all in all; uses two featured items.","correctionPriority":"1) be + past participle (was build, is visit); 2) irregular participles (held, built, taken); 3) comparative forms (more quiet, the most big).","reviseAndRetryFocus":"Turn one fact about the place into the passive, and check each comparison uses -er / -est or more / most correctly.","modelAnswer":"Last summer I spent a weekend in Edinburgh, and I’d definitely recommend it.\n\nTo begin with, we visited Edinburgh Castle, which sits on top of an old volcano. The oldest part was built in the twelfth century. Almost every day, a gun is fired from the castle at one o’clock, a tradition which started in 1861.\n\nIn the afternoon, we walked down the Royal Mile, a busy street where you can find lots of small local shops and cafés. Then we climbed Arthur’s Seat. It was harder than I expected, but the view was the best of the whole trip.\n\nAll in all, Edinburgh is a great destination for a short break. If you go, set off early, because the castle gets very busy by lunchtime.","delayedRecall":"Introduce a venue in your neighbourhood. Say what normally takes place there, give one fact about its past and compare it with another place.","pairedReading":"\"48 hours in Bath\" (travel guide); model set in Edinburgh to avoid repeating Bath"},"conversation":{"scenario":"A weekend visitor asks for tips.","openingLine":"I''m here for the weekend. What should I see?","learnerMoves":"Recommend a place, give one fact about its past, compare it with another place, mention a custom.","targetLanguage":"Passive, defining relative clauses, comparatives and superlatives; local, custom, destination, tradition, set off"},"vocabulary":{"core":[{"target":"tradition","type":"n.","cefr":"B2","use":"B","example":"Visitors are invited to take part in a local tradition."},{"target":"custom","type":"n.","cefr":"B1","use":"P","example":"The guide explained a local custom: visitors are asked to take off their shoes before they go inside."},{"target":"destination","type":"n.","cefr":"B1","use":"P","example":"It''s one of the most popular holiday destinations on the coast."},{"target":"set off","type":"phr. v.","cefr":"B2","use":"B","example":"We set off early to avoid the heavy traffic."},{"target":"get around","type":"phr. v.","cefr":"B1*","use":"P","example":"We were given a map to help us get around the city."},{"target":"unfamiliar","type":"adj.","cefr":"B2","use":"B","example":"We were unfamiliar with the ticket system."},{"target":"welcoming","type":"adj.","cefr":"B2*","use":"B","example":"The hotel where we stayed had a welcoming atmosphere."},{"target":"local","type":"adj.","cefr":"B1","use":"P","example":"Local food is served in the hotel restaurant."}],"collocations":[{"target":"take a guided tour","example":"We took a guided tour of the old town."},{"target":"try the local food","example":"We were encouraged to try the local food."},{"target":"travel light","example":"We travelled light because there wasn''t much room for luggage."},{"target":"stop overnight","example":"We stopped overnight in York before driving on."},{"target":"miss a connection","example":"Our flight was delayed, so we missed our connection."}],"families":[{"base":"culture","forms":["culture","cultural","culturally"],"card":"one productive family card; culturally recognition only"},{"base":"tradition","forms":["traditional","traditionally"],"card":"on tradition"},{"base":"tourism","forms":["tourism","touristy"],"card":"recognition only"}],"optional":[{"target":"break your journey","example":"We broke our journey with an overnight stay in York. Mainly BrE."}],"newCards":14,"note":"Keep passive models in present and past simple. Destination models a superlative and welcoming a defining relative clause. Local means ''from the area''; touristy is often disapproving."},"linkers":[{"target":"to begin with","cefr":"B1","function":"sequence","taughtIn":"writing task","example":"To begin with, we were shown around the old town."},{"target":"what''s more","cefr":"B2","function":"addition","taughtIn":"writing task","example":"The hotel was comfortable. What''s more, breakfast was included."},{"target":"despite","cefr":"B1","function":"concession","taughtIn":"writing task","example":"Despite the rain, the outdoor tour went ahead."},{"target":"all in all","cefr":"B2*","function":"summary","taughtIn":"writing task","example":"All in all, we had an excellent trip."}],"checkpoint1":{"mainItems":4,"lightItems":1,"focus":"Two present passives and two past passives; Light: one relative clause or comparative/superlative"}}],"status":"pilot draft — pending second-teacher review","productionNotes":["Model answers: four recordings (one per week), British English, natural pace (about 130-150 words a minute), with transcripts. Use at least two different speakers across the four weeks and record each speaker''s accent in the audio metadata.","Shadowing chunks: 12 short clips cut from the model recordings, each at normal speed and at 0.8 speed, with transcripts.","Conversation partner: a British synthetic voice labelled as AI, with a 0.9-speed option and live captions; scripts follow the turn maps above, and the partner may vary its wording but stays on the week''s theme and level.","Delayed-recall prompts: text and audio, scheduled 3-5 days after the speaking task.","Checkpoint 1 prompt: text and audio; never shown before the checkpoint.","Safety: conversation transcripts are moderated in both directions, kept under the privacy policy, and every exchange has a report button.","Review before launch: a second teacher checks every model answer, cue card and turn map against the grammar plan and vocabulary list, and listens to every recording."],"reviewChecklist":["[ ] Each wrong option is clearly wrong in its context (no second correct answer).","[ ] Accepted variants cover the common correct answers for rewrite and complete items, including contractions.","[ ] Each reason is one short line a B1 learner can understand.","[ ] Notice-text facts are correct (Week 4: Toledo cathedral begun in 1226; marzipan made in local convents and bakeries).","[ ] Vocabulary in the prompts stays at B1 or uses that week''s featured words.","[ ] Timing checked with 3-5 pilot learners: the set takes 18-22 minutes.","[ ] Items converted to the app''s JSON curriculum format and passed the schema validation.","[ ] Checkpoint 1 items are written separately, not copied from this bank, so the checkpoint tests learning rather than memory of the practice items."],"listening":{"status":"pilot draft — pending second-teacher review","intro":"Nov 21, 2026 · @j","steps":[{"step":"1. Predict","what":"Read the title and a picture caption; note two things you expect to hear","time":"2 min","markedBy":"Not marked"},{"step":"2. Gist","what":"Listen once and answer one question about the main topic","time":"3 min","markedBy":"App"},{"step":"3. Detail","what":"Listen again (pause and replay allowed) and answer six questions","time":"5 min","markedBy":"App"},{"step":"4. Language","what":"Hear three short clips from the track and answer one question on each, on the week''s grammar or featured words","time":"3 min","markedBy":"App"},{"step":"5. Transcript","what":"Read the transcript while listening; tap words to save as personal vocabulary (these count towards the same limit of 5 personal words a week)","time":"Optional","markedBy":"-"},{"step":"6. Respond","what":"Say or write 2-3 sentences in reaction to the track","time":"2 min","markedBy":"AI, light feedback (one correction)"}],"unlocking":"Completing the listening task (steps 2-4) or the reading task counts towards opening the next week.","support":"Speed control (0.8 and 1.0) from the second listen; captions only after step 3. Wrong answers show the line of the transcript where the answer is.","accents":"Across weeks 1-4 learners hear seven British speakers with different regional accents, so they meet the range of British English they will hear in the UK. Each track lists its speakers'' accents in the audio metadata.","length":"Each script is 230-300 words, about 2 minutes at a natural pace (the syllabus range for weeks 1-4).","extensive":{"intro":"Most of the course''s listening comes from the extensive-input library: about 60 minutes a week of graded B1 material with transcripts or captions, tagged to the week''s theme (40 minutes recommended). This is the brief for stocking weeks 1-4.","stock":[{"week":1,"themeTag":"Personal experiences and change","whatToStock":"Short B1 podcast episodes or stories about moving, new jobs and life changes, told in the past","amount":"4-6 items, 5-15 min each"},{"week":2,"themeTag":"Plans, goals and ambitions","whatToStock":"Interviews or podcasts about careers, studying and personal goals","amount":"4-6 items"},{"week":3,"themeTag":"Daily life and social interaction","whatToStock":"Everyday conversations: flat-sharing, neighbours, colleagues, making arrangements","amount":"4-6 items"},{"week":4,"themeTag":"Travel and cultural experiences","whatToStock":"Travel guides, short documentaries and audio tours with captions","amount":"4-6 items"}],"suitable":null,"sources":null,"logging":null},"productionNotes":["Voices: seven British speakers (southern English, Scottish, London, northern English, Welsh, West Midlands, Yorkshire). Use real voice actors where possible; if synthetic voices are used for the pilot, label them in the metadata and replace them before launch.","Pace and quality: natural conversational pace (about 140-160 words a minute), light natural features (fillers, short overlaps) but no background music; studio-quality audio.","Files: one MP3 per track, a WebVTT caption file timed to the script, and three short clips per track for the language step.","Metadata: speakers, accents, length, week, theme tag, and the grammar and featured words the script contains.","[ ] Each question has a single correct answer that is clearly stated in the audio, not only implied.","[ ] Gist questions can be answered after one listen; detail answers appear in the order of the questions.","[ ] True/false items quote the audio closely enough that the answer is not a matter of opinion.","[ ] Facts in the Week 4 script are checked (York Minster finished in 1472; city walls first built by the Romans; the Shambles a former butchers'' street).","[ ] Each script contains the week''s main grammar and at least three featured words, as listed under each week.","[ ] Timing checked with 3-5 pilot learners: the task takes 13-17 minutes.","[ ] A second teacher listens to every recording against the script."],"reviewChecklist":["[ ] Each question has a single correct answer that is clearly stated in the audio, not only implied.","[ ] Gist questions can be answered after one listen; detail answers appear in the order of the questions.","[ ] True/false items quote the audio closely enough that the answer is not a matter of opinion.","[ ] Facts in the Week 4 script are checked (York Minster finished in 1472; city walls first built by the Romans; the Shambles a former butchers'' street).","[ ] Each script contains the week''s main grammar and at least three featured words, as listed under each week.","[ ] Timing checked with 3-5 pilot learners: the task takes 13-17 minutes.","[ ] A second teacher listens to every recording against the script."],"weeks":[{"week":1,"title":"\"Fresh Starts\" podcast","description":"","speakers":"Host (southern English accent); Ellie (Scottish accent).","length":"about 300 words, 2 minutes.","predict":"Title: \"Starting over\". Caption: \"Ellie left the city for a quiet village.\" What might she find difficult?","script":"Host: Welcome back to Fresh Starts, the podcast about big changes. Today I''m talking to Ellie, who moved from London to a small village in Scotland three years ago. Ellie, what was your life like before?\n\nEllie: Busy! I used to work in a bank in the city, and I''d leave home at seven every morning. I''d never really thought about living anywhere else.\n\nHost: So what changed?\n\nEllie: Well, I started working from home, and I realised I didn''t need to live in London any more. My grandmother had left me a small house near Inverness, so I decided to try it for a year.\n\nHost: Was it difficult at first?\n\nEllie: Very. The biggest challenge I faced was the quiet. In London there was always noise, and at first I couldn''t sleep without it. It took me months to get used to the silence. And the nearest supermarket is twenty minutes away by car, so I had to plan everything.\n\nHost: What helped?\n\nEllie: The neighbours, definitely. One evening, while I was trying to fix a broken window, the man from the next house came over to help. Since then, he and his wife have become good friends. They''ve introduced me to almost everyone in the village.\n\nHost: And how are things now?\n\nEllie: I''ve been living here for three years now, and I''ve started a small online business. Gradually, the village has become home. When I look back on that first winter, I can''t believe I nearly went back to London!\n\nHost: Ellie, thank you.","questions":[{"id":"L1-G1","step":"Gist","question":"What is the interview mainly about?","options":["why Ellie lost her job","how Ellie adapted to a new life","how to buy a house in Scotland"],"key":"how Ellie adapted to a new life"},{"id":"L1-D1","step":"Detail","question":"Where did Ellie use to work?","options":["in a bank","in a school","in a supermarket"],"key":"in a bank"},{"id":"L1-D2","step":"Detail","question":"Why did Ellie realise she could leave London?","options":["She started working from home.","She lost her job.","Her grandmother was ill."],"key":"She started working from home."},{"id":"L1-D3","step":"Detail","question":"Ellie bought the house in Scotland.","options":["True","False"],"key":"False (her grandmother had left it to her)"},{"id":"L1-D4","step":"Detail","question":"What was Ellie''s biggest challenge?","options":["the quiet","the weather","the neighbours"],"key":"the quiet"},{"id":"L1-D5","step":"Detail","question":"The nearest supermarket is a twenty-minute walk away.","options":["True","False"],"key":"False (twenty minutes by car)"},{"id":"L1-D6","step":"Detail","question":"How did Ellie meet her neighbour?","options":["He helped her fix a window.","He sold her a car.","They met at the supermarket."],"key":"He helped her fix a window."},{"id":"L1-X1","step":"Language","question":"\"I''d leave home at seven every morning.\" What does I''d mean here?","options":["I would (a past habit)","I had"],"key":"I would (a past habit)"},{"id":"L1-X2","step":"Language","question":"\"My grandmother had left me a small house.\" Did she leave it before or after Ellie decided to move?","options":["before","after"],"key":"before"},{"id":"L1-X3","step":"Language","question":"Complete from the clip: \"It took me months to ___ the silence.\"","options":[],"key":"get used to"}],"respond":"Would you like to live in a village like Ellie''s? Why, or why not?"},{"week":2,"title":"Plans in the office kitchen","description":"","speakers":"Aisha (London accent); Tom (northern English accent).","length":"about 280 words, 2 minutes.","predict":"Title: \"Big plans\". Caption: \"Tom has just booked something important.\" What could it be?","script":"Aisha: Morning, Tom! You look happy.\n\nTom: I am! I''ve just booked my place on a web design course. It starts on the fifth of March.\n\nAisha: Oh, that''s great. Is it something you''ve wanted to do for a while?\n\nTom: Yeah. My goal is to change career in the next two years. I enjoy this job, but I want to do something more creative.\n\nAisha: So are you going to leave?\n\nTom: Not yet. The course is in the evenings, so I''m going to keep working here. I intend to finish it by the summer, and when I finish, I''ll start building a portfolio.\n\nAisha: Sounds like a good plan. What if it''s too much with work?\n\nTom: If it gets too busy, I''ll ask to change my hours. Actually, I''m meeting Sarah from HR on Thursday to talk about it.\n\nAisha: Good idea. I think it''ll be hard work, though.\n\nTom: I know. But I''m really looking forward to learning something new. What about you? Any plans?\n\nAisha: Well, I''d love to do a master''s. If I had the money, I''d apply this year. But it''s really expensive, so I''m saving first.\n\nTom: You should look for a scholarship. My cousin got one last year.\n\nAisha: Really? Maybe I will. The deadline''s probably soon, though.\n\nTom: Then look tonight! As soon as you find one, send it to me. I''ll help you with the application.\n\nAisha: Thanks, Tom. You''re a star.","questions":[{"id":"L2-G1","step":"Gist","question":"What are Tom and Aisha mainly talking about?","options":["their plans for the future","a problem at work","a holiday"],"key":"their plans for the future"},{"id":"L2-D1","step":"Detail","question":"When does Tom''s course start?","options":["5 March","15 March","5 May"],"key":"5 March"},{"id":"L2-D2","step":"Detail","question":"Why does Tom want to change career?","options":["He wants to do something more creative.","He doesn''t like his job.","He wants more money."],"key":"He wants to do something more creative."},{"id":"L2-D3","step":"Detail","question":"Tom is going to leave his job before the course starts.","options":["True","False"],"key":"False (he''s going to keep working)"},{"id":"L2-D4","step":"Detail","question":"What will Tom do when he finishes the course?","options":["build a portfolio","move abroad","start another course"],"key":"build a portfolio"},{"id":"L2-D5","step":"Detail","question":"Who is Tom meeting on Thursday?","options":["Sarah from HR","his cousin","a web designer"],"key":"Sarah from HR"},{"id":"L2-D6","step":"Detail","question":"Why isn''t Aisha applying for a master''s this year?","options":["It''s too expensive.","She''s too busy.","The deadline has passed."],"key":"It''s too expensive."},{"id":"L2-X1","step":"Language","question":"\"I''m meeting Sarah from HR on Thursday.\" Is this an arrangement or a prediction?","options":["an arrangement","a prediction"],"key":"an arrangement"},{"id":"L2-X2","step":"Language","question":"\"If I had the money, I''d apply this year.\" Does Aisha have the money?","options":["Yes","No"],"key":"No"},{"id":"L2-X3","step":"Language","question":"Complete from the clip: \"I''m really ___ learning something new.\"","options":[],"key":"looking forward to"}],"respond":"What''s one thing you''re looking forward to this year, and what will you do to make it happen?"},{"week":3,"title":"A new flatmate''s first day","description":"","speakers":"Dan (Welsh accent); Marta (West Midlands accent).","length":"about 280 words, 2 minutes.","predict":"Title: \"House rules\". Caption: \"Marta moved in yesterday.\" What questions might she ask?","script":"Dan: So this is the kitchen. We have to label our food in the fridge, otherwise Jack eats everything!\n\nMarta: Ha! OK. Is there a cleaning rota?\n\nDan: Yes, it''s on the fridge door. We take turns every week. When it''s your turn, you have to do the bathroom and the kitchen.\n\nMarta: That''s fine. What about the bins?\n\nDan: They go out on Wednesday night. Oh, and you mustn''t put glass in the green bin. The council won''t collect it.\n\nMarta: Good to know. Can I have friends round?\n\nDan: Of course. You don''t have to ask, but it''s polite to tell us if someone''s staying the night.\n\nMarta: Sure. And can I use the washing machine in the evening?\n\nDan: You can use it until ten. After that the neighbours can hear it, so we try not to. If you really need it later, just ask them politely.\n\nMarta: Right. Do you all eat together?\n\nDan: Not really. Everyone has a different routine. I start work early and Jack works late. Apart from that, we all get on with each other really well. We usually go to the pub on Fridays, if you''d like to come.\n\nMarta: I''d love to. Could you tell me how the heating works? I couldn''t turn it on last night.\n\nDan: Ah, it''s a bit strange. You should ask Jack. He can fix anything. I''ll arrange a time for him to show you.\n\nMarta: Perfect. Thanks, Dan.","questions":[{"id":"L3-G1","step":"Gist","question":"What is the conversation mainly about?","options":["the flat''s rules and routines","a problem with the neighbours","looking for a new flat"],"key":"the flat''s rules and routines"},{"id":"L3-D1","step":"Detail","question":"Why do they label their food?","options":["Jack eats everything.","The fridge is small.","The landlord asks them to."],"key":"Jack eats everything."},{"id":"L3-D2","step":"Detail","question":"When do the bins go out?","options":["Wednesday night","Thursday morning","Friday night"],"key":"Wednesday night"},{"id":"L3-D3","step":"Detail","question":"Marta has to ask before inviting friends round.","options":["True","False"],"key":"False (she only needs to tell them if someone stays the night)"},{"id":"L3-D4","step":"Detail","question":"Until what time can Marta use the washing machine?","options":["10 p.m.","8 p.m.","midnight"],"key":"10 p.m."},{"id":"L3-D5","step":"Detail","question":"Why don''t they usually eat together?","options":["They have different routines.","They don''t get on.","The kitchen is too small."],"key":"They have different routines."},{"id":"L3-D6","step":"Detail","question":"Who will show Marta how the heating works?","options":["Jack","Dan","the landlord"],"key":"Jack"},{"id":"L3-X1","step":"Language","question":"\"You mustn''t put glass in the green bin.\" Is this not allowed, or not necessary?","options":["not allowed","not necessary"],"key":"not allowed"},{"id":"L3-X2","step":"Language","question":"\"You don''t have to ask.\" Is this not allowed, or not necessary?","options":["not allowed","not necessary"],"key":"not necessary"},{"id":"L3-X3","step":"Language","question":"Complete from the clip: \"Apart from that, we all ___ each other really well.\"","options":[],"key":"get on with"}],"respond":"Tell a new flatmate one rule in your home and one thing they don''t have to do."},{"week":4,"title":"A walking tour of York","description":"","speakers":"Joanne, tour guide (Yorkshire accent).","length":"about 270 words, 2 minutes.","predict":"Title: \"Welcome to York\". Caption: \"A group of visitors is about to start a tour.\" What places might they see?","script":"Joanne: Good morning, everyone, and welcome to York! My name''s Joanne, and I''ll be your guide this morning. York is one of the oldest cities in England, and it''s a really popular destination. It''s visited by millions of tourists every year. We''ll set off in five minutes, so get your coats on.\n\nOur first stop is York Minster. Work on the cathedral was started in the thirteenth century, and it was finished in 1472, so it took more than two hundred and fifty years to build. It''s one of the largest medieval cathedrals in northern Europe.\n\nAfter that, we''ll walk along the city walls. They were first built by the Romans, and you get the best views of the city from the top. It''s much quieter up there than in the busy streets below.\n\nThen we''ll visit the Shambles, a narrow street where butchers used to sell meat. Today the old shops are used as cafés and gift shops, and it''s one of the most famous streets in the city.\n\nAnd a local custom you might enjoy: every winter, a Christmas market is held in the city centre. It''s become a real tradition, and people travel from all over the country to visit it.\n\nOne more thing. The streets are very old and uneven, so please be careful where you walk. Right, has everyone got their tickets? Let''s go!","questions":[{"id":"L4-G1","step":"Gist","question":"What is Joanne doing?","options":["introducing a walking tour","selling tickets for a museum","talking about her childhood"],"key":"introducing a walking tour"},{"id":"L4-D1","step":"Detail","question":"When was York Minster finished?","options":["1472","1272","1742"],"key":"1472"},{"id":"L4-D2","step":"Detail","question":"How long did it take to build?","options":["more than 250 years","about 50 years","about 100 years"],"key":"more than 250 years"},{"id":"L4-D3","step":"Detail","question":"Who first built the city walls?","options":["the Romans","the Vikings","the Normans"],"key":"the Romans"},{"id":"L4-D4","step":"Detail","question":"It is noisier on the walls than in the streets below.","options":["True","False"],"key":"False (it''s much quieter)"},{"id":"L4-D5","step":"Detail","question":"What did people do in the Shambles in the past?","options":["Butchers sold meat there.","Fishermen sold fish there.","Soldiers guarded the city there."],"key":"Butchers sold meat there."},{"id":"L4-D6","step":"Detail","question":"When is the Christmas market held?","options":["every winter","every summer","every spring"],"key":"every winter"},{"id":"L4-X1","step":"Language","question":"\"It''s visited by millions of tourists every year.\" Is this present or past?","options":["present","past"],"key":"present"},{"id":"L4-X2","step":"Language","question":"Complete from the clip: \"...a narrow street ___ butchers used to sell meat.\"","options":[],"key":"where"},{"id":"L4-X3","step":"Language","question":"Complete from the clip: \"It''s much ___ up there than in the busy streets below.\"","options":[],"key":"quieter"}],"respond":"Tell a visitor about one place in your town: when was it built, and why should they go?"}]},"reading":{"status":"pilot draft — pending second-teacher review","intro":"Nov 21, 2026 · @j","steps":[{"step":"1. Predict","what":"Read the title and first line; note two things you expect the text to say","time":"1 min","markedBy":"Not marked"},{"step":"2. Skim for gist","what":"Read quickly (a 2-minute timer is shown, not enforced) and answer one question about the main idea","time":"2 min","markedBy":"App"},{"step":"3. Read for detail","what":"Read carefully and answer six questions","time":"6 min","markedBy":"App"},{"step":"4. Language","what":"Three questions on the week''s grammar or featured words, using sentences from the text","time":"3 min","markedBy":"App"},{"step":"5. Vocabulary","what":"Tap words to hear them and save them as personal vocabulary (these count towards the limit of 5 personal words a week)","time":"Optional","markedBy":"-"},{"step":"6. Respond","what":"Write 2-3 sentences in reaction to the text","time":"3 min","markedBy":"AI, light feedback (one correction)"}],"unlocking":"Completing the reading task (steps 2-4) or the listening task counts towards opening the next week.","support":"Every text has British-English audio, so learners can read and listen at the same time. Wrong answers highlight the sentence where the answer is.","length":"200-250 words, within the syllabus range for weeks 1-4 (150-250 words).","textTypes":[{"week":1,"type":"Personal blog post","theme":"A Spanish hotel worker''s first year in Manchester"},{"week":2,"type":"Advice column (letter and reply)","theme":"Changing career to teaching"},{"week":3,"type":"Welcome email","theme":"House rules in a shared house"},{"week":4,"type":"Short travel guide","theme":"A weekend in Bath"}],"extensive":{"intro":"Extra reading shares the extensive-input time with listening: about 60 minutes a week in total (40 minutes recommended), tagged to the week''s theme. This is the brief for stocking weeks 1-4.","stock":[{"week":1,"themeTag":"Personal experiences and change","whatToStock":"B1 graded stories and short personal accounts about moving, new jobs and life changes","amount":"3-4 texts or one graded reader chapter per week"},{"week":2,"themeTag":"Plans, goals and ambitions","whatToStock":"Short articles and interviews about careers, studying and goals","amount":"3-4 texts"},{"week":3,"themeTag":"Daily life and social interaction","whatToStock":"Everyday texts: emails, notices, forum posts and short stories about flat-sharing and neighbours","amount":"3-4 texts"},{"week":4,"themeTag":"Travel and cultural experiences","whatToStock":"Short travel guides, blog posts and articles about British places and customs","amount":"3-4 texts"}],"suitable":null,"sources":null,"logging":null},"productionNotes":["Audio: each text read aloud by a British speaker at a natural reading pace, with sentence-level timings so the text can highlight as it is read. Use different regional accents from the listening tracks where possible.","Layout: title, short paragraphs and headings as in the originals; dyslexia-friendly font option; tap-to-hear and tap-to-save on every word.","Metadata: week, theme tag, text type, word count, and the grammar and featured words the text contains.","Answer display: wrong answers highlight the sentence where the answer is.","[ ] Each question has a single correct answer stated clearly in the text.","[ ] Detail questions follow the order of the text.","[ ] Word counts are within 200-250 words, and vocabulary outside the week''s featured items stays at B1.","[ ] British spelling throughout (centre, colour, organise).","[ ] Facts in the Week 4 text are checked (Roman Baths built by the Romans nearly 2,000 years ago; Bath a World Heritage Site since 1987; Royal Crescent of thirty houses built 1767-1774; Pulteney Bridge with shops along both sides; travel time from London).","[ ] Timing checked with 3-5 pilot learners: the task takes 13-17 minutes.","[ ] A second teacher reads every text and question set."],"reviewChecklist":["[ ] Each question has a single correct answer stated clearly in the text.","[ ] Detail questions follow the order of the text.","[ ] Word counts are within 200-250 words, and vocabulary outside the week''s featured items stays at B1.","[ ] British spelling throughout (centre, colour, organise).","[ ] Facts in the Week 4 text are checked (Roman Baths built by the Romans nearly 2,000 years ago; Bath a World Heritage Site since 1987; Royal Crescent of thirty houses built 1767-1774; Pulteney Bridge with shops along both sides; travel time from London).","[ ] Timing checked with 3-5 pilot learners: the task takes 13-17 minutes.","[ ] A second teacher reads every text and question set."],"weeks":[{"week":1,"title":"\"A year in Manchester\" (blog post)","description":"","predict":"Title: \"Lucía''s blog: A year in Manchester\". First line: \"When I moved from Seville to Manchester last October, I thought I was ready.\" Was she ready?","text":"Lucía''s blog: A year in Manchester\n\nWhen I moved from Seville to Manchester last October, I thought I was ready. I had studied English for years, and I had visited the UK twice on holiday. But living here was very different.\n\nThe first challenge I faced was the weather. In Seville I used to eat outside almost every evening, and my friends and I would sit in the square until midnight. In Manchester it was dark by five o''clock, and it rained nearly every day. It took me a long time to get used to it.\n\nWork was hard too. I was working in a busy hotel, and while I was trying to understand my manager''s accent, guests were asking me questions I couldn''t answer. Some days I went home and cried.\n\nThen, in January, a colleague invited me to a Spanish–English conversation group in a café. I had never been to anything like it before, but I decided to go. Since then, I''ve met people from all over the world, and my English has improved a lot. I''ve been going to the group every Tuesday for nine months now.\n\nGradually, Manchester has started to feel like home. I still miss the sun, but when I look back on that first winter, I''m proud that I didn''t give up.","questions":[{"id":"R1-G1","step":"Gist","question":"What is the blog post mainly about?","options":["a holiday in the UK","how Lucía got used to life in Manchester","the weather in Seville"],"key":"how Lucía got used to life in Manchester"},{"id":"R1-D1","step":"Detail","question":"Before she moved, Lucía had never been to the UK.","options":["True","False"],"key":"False (she had visited twice on holiday)"},{"id":"R1-D2","step":"Detail","question":"What did Lucía use to do in Seville in the evenings?","options":["eat outside with friends","work in a hotel","study English"],"key":"eat outside with friends"},{"id":"R1-D3","step":"Detail","question":"What was her first challenge in Manchester?","options":["the weather","the food","finding a flat"],"key":"the weather"},{"id":"R1-D4","step":"Detail","question":"Why was work difficult at first?","options":["It was hard to understand people.","She worked at night.","Her colleagues were unfriendly."],"key":"It was hard to understand people."},{"id":"R1-D5","step":"Detail","question":"Who invited her to the conversation group?","options":["a colleague","a hotel guest","her manager"],"key":"a colleague"},{"id":"R1-D6","step":"Detail","question":"How long has she been going to the group?","options":["nine months","since last October","two years"],"key":"nine months"},{"id":"R1-X1","step":"Language","question":"\"My friends and I would sit in the square until midnight.\" What does would show?","options":["a repeated action in the past","a future plan"],"key":"a repeated action in the past"},{"id":"R1-X2","step":"Language","question":"\"I''ve been going to the group every Tuesday for nine months.\" Does she still go?","options":["Yes","No"],"key":"Yes"},{"id":"R1-X3","step":"Language","question":"Find the word in the last paragraph that means \"slowly, over a period of time\".","options":[],"key":"gradually"}],"respond":"What would you find hardest about moving to a new country, and what would help you?"},{"week":2,"title":"\"Ask Sam\" (advice column)","description":"","predict":"Title: \"Ask Sam: Is it too late to change career?\" First line: \"I''m 28 and I work in a call centre.\" What job might the writer want?","text":"Ask Sam: Is it too late to change career?\n\nDear Sam, I''m 28 and I work in a call centre. My goal is to become a primary school teacher, but I''m worried it''s too late. I intend to apply for a training course, but the deadline is next month and I haven''t decided yet. What should I do? – Daniel\n\nDear Daniel,\n\nIt''s definitely not too late! Many people start a new career in their thirties or forties.\n\nFirst, check exactly what the course needs. If you don''t have the right qualifications, the college will tell you how to get them.\n\nNext, try to get some experience. Could you volunteer at a local school? Many schools are looking for help with reading. If you volunteer for a few hours a week, you''ll find out whether you really enjoy it, and it will look great on your application.\n\nThen apply before the deadline. Even if you don''t get a place this year, you''ll learn a lot from the process, and you can apply again next year.\n\nIf I were you, I''d also talk to some teachers. Most people are happy to talk about their job.\n\nGood luck! I''m sure you''ll make a great teacher, and I''m looking forward to hearing how it goes.\n\nSam","questions":[{"id":"R2-G1","step":"Gist","question":"What does Daniel want?","options":["advice about changing career","help finding a call-centre job","information about schools for his children"],"key":"advice about changing career"},{"id":"R2-D1","step":"Detail","question":"How old is Daniel?","options":["28","38","48"],"key":"28"},{"id":"R2-D2","step":"Detail","question":"What job does Daniel want?","options":["primary school teacher","college lecturer","call-centre manager"],"key":"primary school teacher"},{"id":"R2-D3","step":"Detail","question":"Daniel has already applied for the course.","options":["True","False"],"key":"False (he hasn''t decided yet)"},{"id":"R2-D4","step":"Detail","question":"What does Sam tell him to do first?","options":["check what the course needs","volunteer at a school","talk to teachers"],"key":"check what the course needs"},{"id":"R2-D5","step":"Detail","question":"Why does Sam suggest volunteering?","options":["to find out if he enjoys it","to earn extra money","to meet the college staff"],"key":"to find out if he enjoys it"},{"id":"R2-D6","step":"Detail","question":"What can Daniel do if he doesn''t get a place this year?","options":["apply again next year","ask for his money back","choose a different job"],"key":"apply again next year"},{"id":"R2-X1","step":"Language","question":"\"If I were you, I''d also talk to some teachers.\" What is Sam doing?","options":["giving advice","describing a past event"],"key":"giving advice"},{"id":"R2-X2","step":"Language","question":"\"If you volunteer for a few hours a week, you''ll find out...\" Which form comes after if?","options":["present simple","will"],"key":"present simple"},{"id":"R2-X3","step":"Language","question":"Find the word in Daniel''s letter that means \"the last day you can do something\".","options":[],"key":"deadline"}],"respond":"What advice would you give Daniel? Write 2-3 sentences."},{"week":3,"title":"\"Welcome to 14 Park Road!\" (email)","description":"","predict":"Title: \"Subject: Welcome to 14 Park Road!\" First line: \"We''re all really looking forward to meeting you on Saturday!\" Who is writing, and why?","text":"Subject: Welcome to 14 Park Road!\n\nHi Jess,\n\nWe''re all really looking forward to meeting you on Saturday! Here are a few things you need to know about the house.\n\nBills: We split the bills equally. You have to pay your share by the first of each month. You can just send it to me.\n\nCleaning: There''s a rota on the kitchen wall. Everyone has to clean the kitchen and bathroom once a fortnight. You don''t have to clean other people''s rooms, of course!\n\nNoise: The walls are thin, so you mustn''t play loud music after 11 p.m. on weeknights. On the other hand, nobody minds a bit of noise at weekends.\n\nGuests: You can have friends to stay, but please ask the others politely first if someone is staying more than two nights.\n\nFood: You should label your food, because Sam has a habit of \"borrowing\" things! Apart from that, feel free to use the pans and plates.\n\nWe all have different routines (I work nights twice a week), but we get on with each other really well, and we usually cook together on Sundays. You don''t have to join us, but you''d be very welcome.\n\nCould you tell me what time you''re arriving? I''ll arrange for someone to be in to give you the keys.\n\nSee you soon,\n\nPriya","questions":[{"id":"R3-G1","step":"Gist","question":"Why is Priya writing?","options":["to welcome Jess and explain the house rules","to complain about Sam","to ask Jess to pay a bill"],"key":"to welcome Jess and explain the house rules"},{"id":"R3-D1","step":"Detail","question":"When does Jess have to pay her share of the bills?","options":["by the first of each month","every Sunday","when she arrives"],"key":"by the first of each month"},{"id":"R3-D2","step":"Detail","question":"How often does everyone clean the kitchen and bathroom?","options":["once a fortnight","once a week","once a month"],"key":"once a fortnight"},{"id":"R3-D3","step":"Detail","question":"Loud music is never allowed in the house.","options":["True","False"],"key":"False (only not after 11 p.m. on weeknights)"},{"id":"R3-D4","step":"Detail","question":"When should Jess ask the others before having a guest?","options":["if the guest stays more than two nights","every time","never"],"key":"if the guest stays more than two nights"},{"id":"R3-D5","step":"Detail","question":"Why should Jess label her food?","options":["Sam sometimes takes things.","The fridge is very small.","It''s the landlord''s rule."],"key":"Sam sometimes takes things."},{"id":"R3-D6","step":"Detail","question":"What does Priya want to know?","options":["what time Jess is arriving","whether Jess can cook","when Jess works"],"key":"what time Jess is arriving"},{"id":"R3-X1","step":"Language","question":"\"You don''t have to clean other people''s rooms.\" Is this not allowed, or not necessary?","options":["not allowed","not necessary"],"key":"not necessary"},{"id":"R3-X2","step":"Language","question":"\"You mustn''t play loud music after 11 p.m.\" Is this not allowed, or not necessary?","options":["not allowed","not necessary"],"key":"not allowed"},{"id":"R3-X3","step":"Language","question":"Find the phrase that means \"have a friendly relationship\".","options":[],"key":"get on with"}],"respond":"Write a short reply to Priya: say what time you''re arriving and ask her one question about the house."},{"week":4,"title":"\"48 hours in Bath\" (travel guide)","description":"","predict":"Title: \"48 hours in Bath\". First line: \"Bath is one of the most beautiful cities in England.\" What might a visitor do there?","text":"48 hours in Bath\n\nBath is one of the most beautiful cities in England, and it''s a popular destination for a weekend away. The whole city has been a UNESCO World Heritage Site since 1987.\n\nDay 1. Set off early and start at the Roman Baths. They were built by the Romans nearly 2,000 years ago, and hot water still comes up from the ground today. You can''t swim in the Roman Baths, but just round the corner there''s a modern spa where you can bathe in the same natural hot water. In the afternoon, walk to the Royal Crescent, a curved row of thirty houses which was built between 1767 and 1774.\n\nDay 2. Cross Pulteney Bridge, one of the few bridges in the world with shops along both sides. Then take a walk by the river. It''s quieter than the busy centre, and the views are better. If you visit in November or December, don''t miss the Christmas market, which is held in the streets around the Abbey.\n\nLocal tip. Afternoon tea is a popular local custom. Scones are served with cream and jam, but be careful: in some parts of England, people argue about which one goes on first! It''s a tradition that visitors love.\n\nGetting there. Bath is about 90 minutes from London by train.","questions":[{"id":"R4-G1","step":"Gist","question":"What kind of text is this?","options":["a short travel guide","a history of the Romans","a hotel review"],"key":"a short travel guide"},{"id":"R4-D1","step":"Detail","question":"Since when has Bath been a World Heritage Site?","options":["1987","1767","1774"],"key":"1987"},{"id":"R4-D2","step":"Detail","question":"Who built the Roman Baths?","options":["the Romans","the Victorians","the Normans"],"key":"the Romans"},{"id":"R4-D3","step":"Detail","question":"Visitors can swim in the Roman Baths.","options":["True","False"],"key":"False (they can bathe in a modern spa nearby)"},{"id":"R4-D4","step":"Detail","question":"How many houses are there in the Royal Crescent?","options":["thirty","thirteen","three hundred"],"key":"thirty"},{"id":"R4-D5","step":"Detail","question":"What is special about Pulteney Bridge?","options":["It has shops along both sides.","It is the oldest bridge in England.","It was built by the Romans."],"key":"It has shops along both sides."},{"id":"R4-D6","step":"Detail","question":"Where is the Christmas market held?","options":["in the streets around the Abbey","by the river","at the Roman Baths"],"key":"in the streets around the Abbey"},{"id":"R4-X1","step":"Language","question":"\"They were built by the Romans nearly 2,000 years ago.\" Present or past?","options":["present","past"],"key":"past"},{"id":"R4-X2","step":"Language","question":"Find the word in the first paragraph that means \"a place people travel to\".","options":[],"key":"destination"},{"id":"R4-X3","step":"Language","question":"Complete from the text: \"It''s ___ than the busy centre, and the views are better.\"","options":[],"key":"quieter"}],"respond":"Which place in Bath would you like to visit first, and why?"}]},"writing":{"status":"pilot draft — pending second-teacher review","intro":"Pilot draft, pending second-teacher review. Source: Writing Content PDF (21 Nov 2026), revised so each task matches the repo reading texts.","steps":[{"step":1,"name":"Plan","minutes":5,"what":"required points and optional frame; model hidden"},{"step":2,"name":"Write","minutes":15,"what":"120-150 words in the app, live word count; pasted text flagged"},{"step":3,"name":"Feedback (instant)","minutes":null,"what":"band per criterion, one strength, up to two corrections"},{"step":4,"name":"Revise","minutes":8,"what":"word-by-word comparison of drafts"},{"step":5,"name":"Compare","minutes":2,"what":"model shown with grammar and featured words highlighted"}],"marking":"Writing descriptors (task achievement, vocabulary, grammar, organisation); B1 target; under 100 words caps task achievement at ''Getting there''; British spelling taught, American noted not penalised.","unlocking":"Required: next week opens when speaking, writing and either listening or reading are done.","source":"Writing Content PDF (21 Nov 2026), revised so each task matches the repo reading texts.","weeks":[{"week":1,"title":"A change I got used to"},{"week":2,"title":"A goal and a plan"},{"week":3,"title":"Welcome to the flat"},{"week":4,"title":"A trip worth taking"}],"reviewChecklist":["Each model answer is 120–150 words, covers every required point and uses the week''s grammar, two or more featured words and the named linkers.","Required points are concrete enough for the AI to check (each maps to a form or a piece of content).","Week 4 model facts checked: Edinburgh Castle on an extinct volcano; its oldest part (St Margaret''s Chapel) built in the twelfth century; the One O''Clock Gun fired most days since 1861. The model is set in Edinburgh so it doesn''t repeat the Week 4 reading (Bath).","Correction priorities match the grammar plan and the speaking content for the same week.","AI marking compared with a teacher''s marks on 10–20 sample answers per week before the pilot (agreement on at least 8 in 10).","Timing checked with 3–5 pilot learners: plan, write and revise fit in about 30 minutes.","A second teacher checks every task, frame and model."]}}'::jsonb->'weeks') week(value)
on conflict (week_number) do update set payload = excluded.payload;

insert into public.syllabus_assessments (code, title, payload) values
  ('writing-descriptors', 'Writing descriptors', '{"version":"2026-11-21","note":"Cut scores and thresholds are provisional until the pilot calibrates them.","writingDescriptors":{"intro":"Writing is marked on the same four criteria as speaking, with B1 as the target for weeks 1–4. Learners see ''Getting there'', ''On target'' or ''Beyond target'' for each criterion, never a number.","criteria":[{"key":"task_achievement","label":"Task achievement","gettingThere":"Misses one or more required points, or under 100 words; the reader would be unsure of the purpose.","onTarget":"Covers every required point in 120–150 words; the text suits its reader (a friend, a flatmate, a visitor).","beyondTarget":"Develops every point with detail, reasons or examples, with a clear sense of the reader."},{"key":"vocabulary","label":"Vocabulary","gettingThere":"Basic, repeated words; errors with common words sometimes block meaning.","onTarget":"Enough everyday vocabulary for the topic; at least two of the week''s featured items used correctly; spelling mostly correct.","beyondTarget":"A wider range, accurate collocations, few spelling errors, and paraphrase where a word is missing."},{"key":"grammar","label":"Grammar","gettingThere":"Frequent errors in the week''s main form; some sentences are hard to follow.","onTarget":"The week''s main form used correctly at least once; simple sentences mostly accurate; errors do not block meaning.","beyondTarget":"Main and light forms used accurately; some longer sentences (relative clauses, time clauses, linkers)."},{"key":"organisation","label":"Organisation","gettingThere":"No clear order or paragraphs; few or no linkers.","onTarget":"A clear beginning, middle and end; paragraphs or clear sections; basic linkers, including the week''s linkers.","beyondTarget":"Well-built paragraphs, varied linkers, and a clear opening and closing."}],"rules":["Length. Under 100 words caps task achievement at ''Getting there''. Over 180 words is not penalised, but feedback suggests cutting.","Spelling. British spelling is taught; American spelling is noted once but not marked as an error.","Honesty. Pasted text, or a sudden jump well above the learner''s usual writing, is flagged for teacher review where a teacher is involved. Checkpoint writing has pasting disabled.","Spanish-speaker errors. Typical Spanish-speaker errors (missing subjects, false friends) are corrected like any other error and logged, so later Spanish-specific notes can draw on them."],"learnerFeedback":"A band for each criterion; one strength quoting the learner''s words; up to two corrections, prioritising the week''s grammar, each with the corrected sentence; then revise-and-retry with a word-by-word comparison of the two drafts.","wordRanges":[{"weeks":"1-4","range":"120–150 words","targetBand":"B1"},{"weeks":"5-8","range":"150–180 words","targetBand":"B1"},{"weeks":"9-12","range":"180–200 words","targetBand":"B1+"},{"weeks":"13-16","range":"200–220 words","targetBand":"B1+"},{"weeks":"Stage 2","range":"220–260 words","targetBand":"B2"}]},"speakingDescriptors":{"intro":"The AI gives a band for each of the syllabus''s four criteria; the target for weeks 1-4 is B1. Learners see the bands as \"Getting there\", \"On target\" and \"Beyond target\", never as a number.","criteria":[{"key":"task_achievement","label":"Task achievement","gettingThere":"Covers fewer than three cue points, or under 45 seconds; some content off-task","onTarget":"Covers every cue point in 60-90 seconds; content is relevant and easy to follow","beyondTarget":"Covers every cue point and adds reasons, examples or a personal reaction"},{"key":"vocabulary","label":"Vocabulary","gettingThere":"Basic words only; gaps sometimes stop the meaning","onTarget":"Enough everyday vocabulary for the topic; at least two of the week''s featured items used correctly","beyondTarget":"A wider range, accurate collocations, and paraphrase when a word is missing"},{"key":"grammar","label":"Grammar","gettingThere":"Frequent errors in the week''s main form; meaning sometimes unclear","onTarget":"The week''s main form used correctly at least once; errors do not block meaning","beyondTarget":"Main and light forms used accurately and flexibly; some longer, linked sentences"},{"key":"coherence","label":"Coherence","gettingThere":"Isolated sentences; few or no linking words","onTarget":"A clear order with basic linkers (then, so, because, since then, apart from that)","beyondTarget":"Ideas develop logically with varied linkers and clear signposting"}],"notes":["Not marked automatically: pronunciation and accent. The AI never treats an accent, or a word its speech recognition misheard, as a grammar or vocabulary error. Long pauses are not penalised; where a teacher reviews a recording, they may comment on fluency and pronunciation.","Confidence. If the AI''s bands are uncertain, or the transcript quality is poor, the recording is flagged for teacher review where a teacher is available, and the learner sees \"Feedback may be less accurate for this recording\"."],"learnerFeedback":["1. A band for each criterion.","2. One strength, quoting the learner''s own words.","3. One specific correction, prioritising the week''s main grammar point, with the corrected sentence.","4. A prompt to record again."],"recordings":"Four model answers, British English, natural pace (about 130-150 words a minute), with transcripts; 12 shadowing clips at normal and 0.8 speed with transcripts."},"placement":{"durationMinutes":35,"intro":"Placement takes about 35 minutes at sign-up and sends each learner to the foundation course, Stage 1 or Stage 2. The EF SET starting test is taken alongside it as the progress baseline, but placement makes the decision.","parts":[{"part":"Placement test","time":"15 min","what":"24 questions: 10 grammar, 6 vocabulary, 4 reading (one short text), 4 listening (two short clips)","markedBy":"App"},{"part":"Speaking sample","time":"3 min","what":"''Tell me about your job or studies, and what you''d like to be doing in two years'' time.'' 60 seconds, 30 seconds to plan.","markedBy":"AI, on the placement scale"},{"part":"Writing sample","time":"15 min","what":"''Write 80–100 words about a recent trip or event: what happened and what you enjoyed most.''","markedBy":"AI, on the placement scale"}],"questionBlueprint":[{"level":"A2","questions":6,"focus":"Past simple, comparatives, can / have to, everyday vocabulary"},{"level":"B1","questions":8,"focus":"Present perfect vs past simple, future forms, first conditional, modals, B1 vocabulary"},{"level":"B1+","questions":6,"focus":"Past perfect, passive, second conditional, relative clauses, collocations"},{"level":"B2","questions":4,"focus":"Reported speech, third conditional, modals of deduction, B2 vocabulary"}],"bands":[{"band":"A2","description":"''Getting there'' on most criteria: short, simple sentences; frequent errors that sometimes block meaning."},{"band":"B1","description":"''On target'' on most criteria: the task is done clearly; errors do not block meaning."},{"band":"B1+","description":"''Beyond target'' on most criteria: some range and longer, linked sentences."},{"band":"B2","description":"''Beyond target'' on all criteria: wide range, accurate complex sentences, well organised."}],"decisionRules":[{"outcome":"Foundation course","testScore":"0–11","samples":"Or both samples at A2, whatever the test score."},{"outcome":"Stage 1","testScore":"12–18","samples":"At least one sample at B1 or above."},{"outcome":"Stage 2","testScore":"19–24","samples":"Both samples at B1+ or above."}],"borderline":"If the score is within one point of a boundary, or the test and samples point to different results, place the learner in the lower option and tell them they can take a short move-up check after week 2. Where a teacher is involved, they review borderline cases first.","learnerChoice":"A learner placed in Stage 2 may choose to start at Stage 1. A learner placed in the foundation course is shown why, with links to suitable A2 material.","efSetCrossCheck":"If the EF SET result differs from the placement by a full CEFR level or more, the placement is flagged for review; it is not changed automatically."},"checkpoint1":{"intro":"A course checkpoint, not a CEFR placement or certification test. It assesses B1 grammar, a short spoken narrative and a 150-word piece, and is reported beside the learner''s EF SET starting test.","quiz":{"scoredItems":20,"reserveItems":4,"blueprint":"Four Main items and one Light item per week, written separately from the practice item bank so the checkpoint tests learning, not memory of practice items. Order: weeks 1–4, Main then Light. Exclude stretch tasks.","delivery":"Each item is auto-marked; the reason is shown only after the whole checkpoint is submitted. Short scenarios and answer keys allow valid variants; if two options are grammatical, ask which better expresses the stated meaning or accept both.","reporting":"Report results by skill and recommend a specific practice item."},"items":[{"id":"CP1-01","week":1,"target":"Main: finished time","prompt":"We ___ the Colosseum when we were in Rome in 2019.","options":["visited","have visited"],"key":"visited","reason":"''In 2019'' is a finished time."},{"id":"CP1-02","week":1,"target":"Main: past to now","prompt":"My brother ___ three different jobs since he left university.","options":["had","has had"],"key":"has had","reason":"''Since he left'' connects the past to now."},{"id":"CP1-03","week":1,"target":"Main: background","prompt":"The sun ___ (shine) when we left the hotel.","options":[],"key":"was shining","reason":"Background to the main event."},{"id":"CP1-04","week":1,"target":"Main: sequence","prompt":"When I opened the fridge, I realised someone ___ (eat) my cake.","options":[],"key":"had eaten","reason":"It happened before I opened the fridge."},{"id":"CP1-05","week":1,"target":"Light","prompt":"As a teenager, I ___ have very long hair.","options":["used to","would"],"key":"used to","reason":"''Have'' (possession) is a state, so would is not possible."},{"id":"CP1-06","week":2,"target":"Main: intention","prompt":"A: Any plans for the summer? B: I ___ visit my cousins in Ireland, but I haven''t booked anything yet.","options":["''m going to","''m visiting"],"key":"''m going to","reason":"An intention with nothing arranged yet."},{"id":"CP1-07","week":2,"target":"Main: arrangement","prompt":"We ___ (fly) to Lisbon on Friday. The tickets are in my bag.","options":[],"key":"''re flying (are flying)","reason":"A fixed arrangement."},{"id":"CP1-08","week":2,"target":"Main: time clause","prompt":"I''ll send you the photos when I ___ home.","options":["get","''ll get"],"key":"get","reason":"After ''when'', use the present simple for the future."},{"id":"CP1-09","week":2,"target":"Main: time clause","prompt":"As soon as the film ___ (finish), we''ll go for dinner.","options":[],"key":"finishes","reason":"After ''as soon as'', use the present simple for the future."},{"id":"CP1-10","week":2,"target":"Light","prompt":"If I ___ the lottery, I''d buy a house by the sea.","options":["won","win"],"key":"won","reason":"Second conditional: an imagined situation."},{"id":"CP1-11","week":3,"target":"Main: obligation","prompt":"In the UK, you ___ drive on the left.","options":["have to","don''t have to"],"key":"have to","reason":"It is a rule."},{"id":"CP1-12","week":3,"target":"Main: advice","prompt":"If you want to improve your English, you ___ read a little every day.","options":["should","mustn''t"],"key":"should","reason":"Advice."},{"id":"CP1-13","week":3,"target":"Main: ability","prompt":"My grandmother ___ (can / not / use) a smartphone, so we phone her.","options":[],"key":"can''t use (cannot use)","reason":"Ability, negative."},{"id":"CP1-14","week":3,"target":"Main: permission","prompt":"___ I leave my bag here while I go to the toilet?","options":["Can","Must"],"key":"Can (Could)","reason":"Asking for permission."},{"id":"CP1-15","week":3,"target":"Light","prompt":"Put the words in order: Where / you / do / work?","options":[],"key":"Where do you work?","reason":"Auxiliary before the subject."},{"id":"CP1-16","week":4,"target":"Main: present passive","prompt":"Cheese ___ (make) from milk.","options":[],"key":"is made","reason":"A general fact; the cheese is the focus."},{"id":"CP1-17","week":4,"target":"Main: present passive","prompt":"Most of the city''s buses ___ by electricity now.","options":["are powered","power"],"key":"are powered","reason":"Something powers the buses."},{"id":"CP1-18","week":4,"target":"Main: past passive","prompt":"The first email ___ (send) in 1971.","options":[],"key":"was sent","reason":"Past passive."},{"id":"CP1-19","week":4,"target":"Main: past passive","prompt":"Our flight ___ because of the snow.","options":["was cancelled","cancelled"],"key":"was cancelled","reason":"The airline cancelled it."},{"id":"CP1-20","week":4,"target":"Light","prompt":"This is the hotel ___ we stayed last summer.","options":["where","who"],"key":"where","reason":"''Where'' for a place followed by a full clause."}],"reserves":[{"id":"CP1-R1","week":1,"target":"reserve","prompt":"I ___ (not / see) her since the wedding.","options":[],"key":"haven''t seen (have not seen)","reason":"Up to now with since."},{"id":"CP1-R2","week":2,"target":"reserve","prompt":"Don''t worry, I ___ (call) you before I ___ (leave).","options":[],"key":"''ll call ... leave","reason":"Will for the promise; present simple after before."},{"id":"CP1-R3","week":3,"target":"reserve","prompt":"You ___ (not / have to) come to the party if you''re tired.","options":[],"key":"don''t have to","reason":"It isn''t necessary."},{"id":"CP1-R4","week":4,"target":"reserve","prompt":"The Alhambra ___ (visit) by millions of people every year.","options":[],"key":"is visited","reason":"Present passive with by."}],"reserveUse":"Reserves replace an item that pilot data shows is unclear, or form a retake for learners repeating the checkpoint.","writing":{"prompts":[{"label":"A. A change I got used to","text":"Describe how life was before a change, what happened, what was difficult, and how things are now."},{"label":"B. A note for a visitor","text":"A friend is visiting your town for a weekend. Recommend what to see: include a regular event or custom, one fact about a place''s past, a comparison, and one piece of advice."}],"conditions":[{"id":"length","setting":"Length","value":"150 words (130–170 accepted)"},{"id":"time","setting":"Time","value":"30 minutes, with a visible timer"},{"id":"where","setting":"Where","value":"In the app; pasting disabled; no phrase bank or model"},{"id":"attempts","setting":"Attempts","value":"One submission; no revise-and-retry"},{"id":"marking","setting":"Marking","value":"AI bands on the four writing criteria straight away; a teacher confirms where one is involved, and the teacher''s mark counts"}],"onTarget":"''On target'' or better on at least three criteria, task achievement not ''Getting there''. Results guide practice; they never block week 5."},"result":{"intro":"Results are reported by part and by week, never as pass or fail. Learners continue to week 5 whatever their result; the checkpoint guides practice, it does not block progress.","thresholds":[{"part":"Quiz","onTarget":"14 of 20 or more (70%)"},{"part":"Speaking","onTarget":"''On target'' or better on at least three criteria, and task achievement not at ''Getting there''"},{"part":"Writing","onTarget":"''On target'' or better on at least three criteria, and task achievement not at ''Getting there''"}],"practiceLinks":"Each part below target links to the matching practice: weak quiz items to that week''s extra items and grammar clinic, speaking to the week''s shadowing and conversation, writing to a revise-and-retry task on the same prompt."},"calibration":["A second teacher checks every checkpoint item for a single correct answer and accepted variants.","Check the existing 24 placement questions against the blueprint (6 A2, 8 B1, 6 B1+, 4 B2) and replace those that do not fit.","Mark 10–20 sample texts and recordings by hand and compare with the AI''s bands; adjust prompts until they agree on at least 8 in 10.","After 30 placed learners, compare placement with EF SET results and adjust the cut scores (11/12 and 18/19).","Review any checkpoint item that more than 90% or fewer than 30% of pilot learners answer correctly.","Confirm the checkpoint thresholds (70% quiz, three of four criteria) against teacher judgement of pilot learners."],"speaking":{"status":"pilot draft — pending second-teacher review","intro":"After week 4, learners record one short spoken narrative under checkpoint conditions, marked with the same four descriptors.","prompt":"Talk about a time when you had to adapt to something new: a job, a place, a course or a routine. What was it like before, what happened, and how are things now? If you like, say what you would tell someone in the same situation.","conditions":[{"setting":"Planning","value":"1 minute; notes allowed, no phrase bank or model"},{"setting":"Length","value":"60-90 seconds"},{"setting":"Attempts","value":"One recording; no retry (practice tasks allow retries, checkpoints do not)"},{"setting":"Marking","value":"AI bands on the four criteria straight away; a teacher confirms where one is involved, and the teacher''s mark counts"},{"setting":"On target","value":"\"On target\" or better on at least three of the four criteria, with no criterion at \"Getting there\" for task achievement"},{"setting":"Language it draws on","value":"Weeks 1-4: narrative tenses, present perfect, used to / would, modals for advice; featured vocabulary from any of the four weeks"}],"transferNote":"The prompt is new, so it tests transfer rather than memory of a practised answer."}},"status":"pilot draft — pending second-teacher review","sources":["Writing descriptors, placement and checkpoint 1 (21 Nov 2026)","Fluency Studio: Weeks 1–4 Speaking Content (21 Nov 2026)"]}'::jsonb->'writingDescriptors'),
  ('speaking-descriptors', 'Speaking descriptors', '{"version":"2026-11-21","note":"Cut scores and thresholds are provisional until the pilot calibrates them.","writingDescriptors":{"intro":"Writing is marked on the same four criteria as speaking, with B1 as the target for weeks 1–4. Learners see ''Getting there'', ''On target'' or ''Beyond target'' for each criterion, never a number.","criteria":[{"key":"task_achievement","label":"Task achievement","gettingThere":"Misses one or more required points, or under 100 words; the reader would be unsure of the purpose.","onTarget":"Covers every required point in 120–150 words; the text suits its reader (a friend, a flatmate, a visitor).","beyondTarget":"Develops every point with detail, reasons or examples, with a clear sense of the reader."},{"key":"vocabulary","label":"Vocabulary","gettingThere":"Basic, repeated words; errors with common words sometimes block meaning.","onTarget":"Enough everyday vocabulary for the topic; at least two of the week''s featured items used correctly; spelling mostly correct.","beyondTarget":"A wider range, accurate collocations, few spelling errors, and paraphrase where a word is missing."},{"key":"grammar","label":"Grammar","gettingThere":"Frequent errors in the week''s main form; some sentences are hard to follow.","onTarget":"The week''s main form used correctly at least once; simple sentences mostly accurate; errors do not block meaning.","beyondTarget":"Main and light forms used accurately; some longer sentences (relative clauses, time clauses, linkers)."},{"key":"organisation","label":"Organisation","gettingThere":"No clear order or paragraphs; few or no linkers.","onTarget":"A clear beginning, middle and end; paragraphs or clear sections; basic linkers, including the week''s linkers.","beyondTarget":"Well-built paragraphs, varied linkers, and a clear opening and closing."}],"rules":["Length. Under 100 words caps task achievement at ''Getting there''. Over 180 words is not penalised, but feedback suggests cutting.","Spelling. British spelling is taught; American spelling is noted once but not marked as an error.","Honesty. Pasted text, or a sudden jump well above the learner''s usual writing, is flagged for teacher review where a teacher is involved. Checkpoint writing has pasting disabled.","Spanish-speaker errors. Typical Spanish-speaker errors (missing subjects, false friends) are corrected like any other error and logged, so later Spanish-specific notes can draw on them."],"learnerFeedback":"A band for each criterion; one strength quoting the learner''s words; up to two corrections, prioritising the week''s grammar, each with the corrected sentence; then revise-and-retry with a word-by-word comparison of the two drafts.","wordRanges":[{"weeks":"1-4","range":"120–150 words","targetBand":"B1"},{"weeks":"5-8","range":"150–180 words","targetBand":"B1"},{"weeks":"9-12","range":"180–200 words","targetBand":"B1+"},{"weeks":"13-16","range":"200–220 words","targetBand":"B1+"},{"weeks":"Stage 2","range":"220–260 words","targetBand":"B2"}]},"speakingDescriptors":{"intro":"The AI gives a band for each of the syllabus''s four criteria; the target for weeks 1-4 is B1. Learners see the bands as \"Getting there\", \"On target\" and \"Beyond target\", never as a number.","criteria":[{"key":"task_achievement","label":"Task achievement","gettingThere":"Covers fewer than three cue points, or under 45 seconds; some content off-task","onTarget":"Covers every cue point in 60-90 seconds; content is relevant and easy to follow","beyondTarget":"Covers every cue point and adds reasons, examples or a personal reaction"},{"key":"vocabulary","label":"Vocabulary","gettingThere":"Basic words only; gaps sometimes stop the meaning","onTarget":"Enough everyday vocabulary for the topic; at least two of the week''s featured items used correctly","beyondTarget":"A wider range, accurate collocations, and paraphrase when a word is missing"},{"key":"grammar","label":"Grammar","gettingThere":"Frequent errors in the week''s main form; meaning sometimes unclear","onTarget":"The week''s main form used correctly at least once; errors do not block meaning","beyondTarget":"Main and light forms used accurately and flexibly; some longer, linked sentences"},{"key":"coherence","label":"Coherence","gettingThere":"Isolated sentences; few or no linking words","onTarget":"A clear order with basic linkers (then, so, because, since then, apart from that)","beyondTarget":"Ideas develop logically with varied linkers and clear signposting"}],"notes":["Not marked automatically: pronunciation and accent. The AI never treats an accent, or a word its speech recognition misheard, as a grammar or vocabulary error. Long pauses are not penalised; where a teacher reviews a recording, they may comment on fluency and pronunciation.","Confidence. If the AI''s bands are uncertain, or the transcript quality is poor, the recording is flagged for teacher review where a teacher is available, and the learner sees \"Feedback may be less accurate for this recording\"."],"learnerFeedback":["1. A band for each criterion.","2. One strength, quoting the learner''s own words.","3. One specific correction, prioritising the week''s main grammar point, with the corrected sentence.","4. A prompt to record again."],"recordings":"Four model answers, British English, natural pace (about 130-150 words a minute), with transcripts; 12 shadowing clips at normal and 0.8 speed with transcripts."},"placement":{"durationMinutes":35,"intro":"Placement takes about 35 minutes at sign-up and sends each learner to the foundation course, Stage 1 or Stage 2. The EF SET starting test is taken alongside it as the progress baseline, but placement makes the decision.","parts":[{"part":"Placement test","time":"15 min","what":"24 questions: 10 grammar, 6 vocabulary, 4 reading (one short text), 4 listening (two short clips)","markedBy":"App"},{"part":"Speaking sample","time":"3 min","what":"''Tell me about your job or studies, and what you''d like to be doing in two years'' time.'' 60 seconds, 30 seconds to plan.","markedBy":"AI, on the placement scale"},{"part":"Writing sample","time":"15 min","what":"''Write 80–100 words about a recent trip or event: what happened and what you enjoyed most.''","markedBy":"AI, on the placement scale"}],"questionBlueprint":[{"level":"A2","questions":6,"focus":"Past simple, comparatives, can / have to, everyday vocabulary"},{"level":"B1","questions":8,"focus":"Present perfect vs past simple, future forms, first conditional, modals, B1 vocabulary"},{"level":"B1+","questions":6,"focus":"Past perfect, passive, second conditional, relative clauses, collocations"},{"level":"B2","questions":4,"focus":"Reported speech, third conditional, modals of deduction, B2 vocabulary"}],"bands":[{"band":"A2","description":"''Getting there'' on most criteria: short, simple sentences; frequent errors that sometimes block meaning."},{"band":"B1","description":"''On target'' on most criteria: the task is done clearly; errors do not block meaning."},{"band":"B1+","description":"''Beyond target'' on most criteria: some range and longer, linked sentences."},{"band":"B2","description":"''Beyond target'' on all criteria: wide range, accurate complex sentences, well organised."}],"decisionRules":[{"outcome":"Foundation course","testScore":"0–11","samples":"Or both samples at A2, whatever the test score."},{"outcome":"Stage 1","testScore":"12–18","samples":"At least one sample at B1 or above."},{"outcome":"Stage 2","testScore":"19–24","samples":"Both samples at B1+ or above."}],"borderline":"If the score is within one point of a boundary, or the test and samples point to different results, place the learner in the lower option and tell them they can take a short move-up check after week 2. Where a teacher is involved, they review borderline cases first.","learnerChoice":"A learner placed in Stage 2 may choose to start at Stage 1. A learner placed in the foundation course is shown why, with links to suitable A2 material.","efSetCrossCheck":"If the EF SET result differs from the placement by a full CEFR level or more, the placement is flagged for review; it is not changed automatically."},"checkpoint1":{"intro":"A course checkpoint, not a CEFR placement or certification test. It assesses B1 grammar, a short spoken narrative and a 150-word piece, and is reported beside the learner''s EF SET starting test.","quiz":{"scoredItems":20,"reserveItems":4,"blueprint":"Four Main items and one Light item per week, written separately from the practice item bank so the checkpoint tests learning, not memory of practice items. Order: weeks 1–4, Main then Light. Exclude stretch tasks.","delivery":"Each item is auto-marked; the reason is shown only after the whole checkpoint is submitted. Short scenarios and answer keys allow valid variants; if two options are grammatical, ask which better expresses the stated meaning or accept both.","reporting":"Report results by skill and recommend a specific practice item."},"items":[{"id":"CP1-01","week":1,"target":"Main: finished time","prompt":"We ___ the Colosseum when we were in Rome in 2019.","options":["visited","have visited"],"key":"visited","reason":"''In 2019'' is a finished time."},{"id":"CP1-02","week":1,"target":"Main: past to now","prompt":"My brother ___ three different jobs since he left university.","options":["had","has had"],"key":"has had","reason":"''Since he left'' connects the past to now."},{"id":"CP1-03","week":1,"target":"Main: background","prompt":"The sun ___ (shine) when we left the hotel.","options":[],"key":"was shining","reason":"Background to the main event."},{"id":"CP1-04","week":1,"target":"Main: sequence","prompt":"When I opened the fridge, I realised someone ___ (eat) my cake.","options":[],"key":"had eaten","reason":"It happened before I opened the fridge."},{"id":"CP1-05","week":1,"target":"Light","prompt":"As a teenager, I ___ have very long hair.","options":["used to","would"],"key":"used to","reason":"''Have'' (possession) is a state, so would is not possible."},{"id":"CP1-06","week":2,"target":"Main: intention","prompt":"A: Any plans for the summer? B: I ___ visit my cousins in Ireland, but I haven''t booked anything yet.","options":["''m going to","''m visiting"],"key":"''m going to","reason":"An intention with nothing arranged yet."},{"id":"CP1-07","week":2,"target":"Main: arrangement","prompt":"We ___ (fly) to Lisbon on Friday. The tickets are in my bag.","options":[],"key":"''re flying (are flying)","reason":"A fixed arrangement."},{"id":"CP1-08","week":2,"target":"Main: time clause","prompt":"I''ll send you the photos when I ___ home.","options":["get","''ll get"],"key":"get","reason":"After ''when'', use the present simple for the future."},{"id":"CP1-09","week":2,"target":"Main: time clause","prompt":"As soon as the film ___ (finish), we''ll go for dinner.","options":[],"key":"finishes","reason":"After ''as soon as'', use the present simple for the future."},{"id":"CP1-10","week":2,"target":"Light","prompt":"If I ___ the lottery, I''d buy a house by the sea.","options":["won","win"],"key":"won","reason":"Second conditional: an imagined situation."},{"id":"CP1-11","week":3,"target":"Main: obligation","prompt":"In the UK, you ___ drive on the left.","options":["have to","don''t have to"],"key":"have to","reason":"It is a rule."},{"id":"CP1-12","week":3,"target":"Main: advice","prompt":"If you want to improve your English, you ___ read a little every day.","options":["should","mustn''t"],"key":"should","reason":"Advice."},{"id":"CP1-13","week":3,"target":"Main: ability","prompt":"My grandmother ___ (can / not / use) a smartphone, so we phone her.","options":[],"key":"can''t use (cannot use)","reason":"Ability, negative."},{"id":"CP1-14","week":3,"target":"Main: permission","prompt":"___ I leave my bag here while I go to the toilet?","options":["Can","Must"],"key":"Can (Could)","reason":"Asking for permission."},{"id":"CP1-15","week":3,"target":"Light","prompt":"Put the words in order: Where / you / do / work?","options":[],"key":"Where do you work?","reason":"Auxiliary before the subject."},{"id":"CP1-16","week":4,"target":"Main: present passive","prompt":"Cheese ___ (make) from milk.","options":[],"key":"is made","reason":"A general fact; the cheese is the focus."},{"id":"CP1-17","week":4,"target":"Main: present passive","prompt":"Most of the city''s buses ___ by electricity now.","options":["are powered","power"],"key":"are powered","reason":"Something powers the buses."},{"id":"CP1-18","week":4,"target":"Main: past passive","prompt":"The first email ___ (send) in 1971.","options":[],"key":"was sent","reason":"Past passive."},{"id":"CP1-19","week":4,"target":"Main: past passive","prompt":"Our flight ___ because of the snow.","options":["was cancelled","cancelled"],"key":"was cancelled","reason":"The airline cancelled it."},{"id":"CP1-20","week":4,"target":"Light","prompt":"This is the hotel ___ we stayed last summer.","options":["where","who"],"key":"where","reason":"''Where'' for a place followed by a full clause."}],"reserves":[{"id":"CP1-R1","week":1,"target":"reserve","prompt":"I ___ (not / see) her since the wedding.","options":[],"key":"haven''t seen (have not seen)","reason":"Up to now with since."},{"id":"CP1-R2","week":2,"target":"reserve","prompt":"Don''t worry, I ___ (call) you before I ___ (leave).","options":[],"key":"''ll call ... leave","reason":"Will for the promise; present simple after before."},{"id":"CP1-R3","week":3,"target":"reserve","prompt":"You ___ (not / have to) come to the party if you''re tired.","options":[],"key":"don''t have to","reason":"It isn''t necessary."},{"id":"CP1-R4","week":4,"target":"reserve","prompt":"The Alhambra ___ (visit) by millions of people every year.","options":[],"key":"is visited","reason":"Present passive with by."}],"reserveUse":"Reserves replace an item that pilot data shows is unclear, or form a retake for learners repeating the checkpoint.","writing":{"prompts":[{"label":"A. A change I got used to","text":"Describe how life was before a change, what happened, what was difficult, and how things are now."},{"label":"B. A note for a visitor","text":"A friend is visiting your town for a weekend. Recommend what to see: include a regular event or custom, one fact about a place''s past, a comparison, and one piece of advice."}],"conditions":[{"id":"length","setting":"Length","value":"150 words (130–170 accepted)"},{"id":"time","setting":"Time","value":"30 minutes, with a visible timer"},{"id":"where","setting":"Where","value":"In the app; pasting disabled; no phrase bank or model"},{"id":"attempts","setting":"Attempts","value":"One submission; no revise-and-retry"},{"id":"marking","setting":"Marking","value":"AI bands on the four writing criteria straight away; a teacher confirms where one is involved, and the teacher''s mark counts"}],"onTarget":"''On target'' or better on at least three criteria, task achievement not ''Getting there''. Results guide practice; they never block week 5."},"result":{"intro":"Results are reported by part and by week, never as pass or fail. Learners continue to week 5 whatever their result; the checkpoint guides practice, it does not block progress.","thresholds":[{"part":"Quiz","onTarget":"14 of 20 or more (70%)"},{"part":"Speaking","onTarget":"''On target'' or better on at least three criteria, and task achievement not at ''Getting there''"},{"part":"Writing","onTarget":"''On target'' or better on at least three criteria, and task achievement not at ''Getting there''"}],"practiceLinks":"Each part below target links to the matching practice: weak quiz items to that week''s extra items and grammar clinic, speaking to the week''s shadowing and conversation, writing to a revise-and-retry task on the same prompt."},"calibration":["A second teacher checks every checkpoint item for a single correct answer and accepted variants.","Check the existing 24 placement questions against the blueprint (6 A2, 8 B1, 6 B1+, 4 B2) and replace those that do not fit.","Mark 10–20 sample texts and recordings by hand and compare with the AI''s bands; adjust prompts until they agree on at least 8 in 10.","After 30 placed learners, compare placement with EF SET results and adjust the cut scores (11/12 and 18/19).","Review any checkpoint item that more than 90% or fewer than 30% of pilot learners answer correctly.","Confirm the checkpoint thresholds (70% quiz, three of four criteria) against teacher judgement of pilot learners."],"speaking":{"status":"pilot draft — pending second-teacher review","intro":"After week 4, learners record one short spoken narrative under checkpoint conditions, marked with the same four descriptors.","prompt":"Talk about a time when you had to adapt to something new: a job, a place, a course or a routine. What was it like before, what happened, and how are things now? If you like, say what you would tell someone in the same situation.","conditions":[{"setting":"Planning","value":"1 minute; notes allowed, no phrase bank or model"},{"setting":"Length","value":"60-90 seconds"},{"setting":"Attempts","value":"One recording; no retry (practice tasks allow retries, checkpoints do not)"},{"setting":"Marking","value":"AI bands on the four criteria straight away; a teacher confirms where one is involved, and the teacher''s mark counts"},{"setting":"On target","value":"\"On target\" or better on at least three of the four criteria, with no criterion at \"Getting there\" for task achievement"},{"setting":"Language it draws on","value":"Weeks 1-4: narrative tenses, present perfect, used to / would, modals for advice; featured vocabulary from any of the four weeks"}],"transferNote":"The prompt is new, so it tests transfer rather than memory of a practised answer."}},"status":"pilot draft — pending second-teacher review","sources":["Writing descriptors, placement and checkpoint 1 (21 Nov 2026)","Fluency Studio: Weeks 1–4 Speaking Content (21 Nov 2026)"]}'::jsonb->'speakingDescriptors'),
  ('placement', 'Placement', '{"version":"2026-11-21","note":"Cut scores and thresholds are provisional until the pilot calibrates them.","writingDescriptors":{"intro":"Writing is marked on the same four criteria as speaking, with B1 as the target for weeks 1–4. Learners see ''Getting there'', ''On target'' or ''Beyond target'' for each criterion, never a number.","criteria":[{"key":"task_achievement","label":"Task achievement","gettingThere":"Misses one or more required points, or under 100 words; the reader would be unsure of the purpose.","onTarget":"Covers every required point in 120–150 words; the text suits its reader (a friend, a flatmate, a visitor).","beyondTarget":"Develops every point with detail, reasons or examples, with a clear sense of the reader."},{"key":"vocabulary","label":"Vocabulary","gettingThere":"Basic, repeated words; errors with common words sometimes block meaning.","onTarget":"Enough everyday vocabulary for the topic; at least two of the week''s featured items used correctly; spelling mostly correct.","beyondTarget":"A wider range, accurate collocations, few spelling errors, and paraphrase where a word is missing."},{"key":"grammar","label":"Grammar","gettingThere":"Frequent errors in the week''s main form; some sentences are hard to follow.","onTarget":"The week''s main form used correctly at least once; simple sentences mostly accurate; errors do not block meaning.","beyondTarget":"Main and light forms used accurately; some longer sentences (relative clauses, time clauses, linkers)."},{"key":"organisation","label":"Organisation","gettingThere":"No clear order or paragraphs; few or no linkers.","onTarget":"A clear beginning, middle and end; paragraphs or clear sections; basic linkers, including the week''s linkers.","beyondTarget":"Well-built paragraphs, varied linkers, and a clear opening and closing."}],"rules":["Length. Under 100 words caps task achievement at ''Getting there''. Over 180 words is not penalised, but feedback suggests cutting.","Spelling. British spelling is taught; American spelling is noted once but not marked as an error.","Honesty. Pasted text, or a sudden jump well above the learner''s usual writing, is flagged for teacher review where a teacher is involved. Checkpoint writing has pasting disabled.","Spanish-speaker errors. Typical Spanish-speaker errors (missing subjects, false friends) are corrected like any other error and logged, so later Spanish-specific notes can draw on them."],"learnerFeedback":"A band for each criterion; one strength quoting the learner''s words; up to two corrections, prioritising the week''s grammar, each with the corrected sentence; then revise-and-retry with a word-by-word comparison of the two drafts.","wordRanges":[{"weeks":"1-4","range":"120–150 words","targetBand":"B1"},{"weeks":"5-8","range":"150–180 words","targetBand":"B1"},{"weeks":"9-12","range":"180–200 words","targetBand":"B1+"},{"weeks":"13-16","range":"200–220 words","targetBand":"B1+"},{"weeks":"Stage 2","range":"220–260 words","targetBand":"B2"}]},"speakingDescriptors":{"intro":"The AI gives a band for each of the syllabus''s four criteria; the target for weeks 1-4 is B1. Learners see the bands as \"Getting there\", \"On target\" and \"Beyond target\", never as a number.","criteria":[{"key":"task_achievement","label":"Task achievement","gettingThere":"Covers fewer than three cue points, or under 45 seconds; some content off-task","onTarget":"Covers every cue point in 60-90 seconds; content is relevant and easy to follow","beyondTarget":"Covers every cue point and adds reasons, examples or a personal reaction"},{"key":"vocabulary","label":"Vocabulary","gettingThere":"Basic words only; gaps sometimes stop the meaning","onTarget":"Enough everyday vocabulary for the topic; at least two of the week''s featured items used correctly","beyondTarget":"A wider range, accurate collocations, and paraphrase when a word is missing"},{"key":"grammar","label":"Grammar","gettingThere":"Frequent errors in the week''s main form; meaning sometimes unclear","onTarget":"The week''s main form used correctly at least once; errors do not block meaning","beyondTarget":"Main and light forms used accurately and flexibly; some longer, linked sentences"},{"key":"coherence","label":"Coherence","gettingThere":"Isolated sentences; few or no linking words","onTarget":"A clear order with basic linkers (then, so, because, since then, apart from that)","beyondTarget":"Ideas develop logically with varied linkers and clear signposting"}],"notes":["Not marked automatically: pronunciation and accent. The AI never treats an accent, or a word its speech recognition misheard, as a grammar or vocabulary error. Long pauses are not penalised; where a teacher reviews a recording, they may comment on fluency and pronunciation.","Confidence. If the AI''s bands are uncertain, or the transcript quality is poor, the recording is flagged for teacher review where a teacher is available, and the learner sees \"Feedback may be less accurate for this recording\"."],"learnerFeedback":["1. A band for each criterion.","2. One strength, quoting the learner''s own words.","3. One specific correction, prioritising the week''s main grammar point, with the corrected sentence.","4. A prompt to record again."],"recordings":"Four model answers, British English, natural pace (about 130-150 words a minute), with transcripts; 12 shadowing clips at normal and 0.8 speed with transcripts."},"placement":{"durationMinutes":35,"intro":"Placement takes about 35 minutes at sign-up and sends each learner to the foundation course, Stage 1 or Stage 2. The EF SET starting test is taken alongside it as the progress baseline, but placement makes the decision.","parts":[{"part":"Placement test","time":"15 min","what":"24 questions: 10 grammar, 6 vocabulary, 4 reading (one short text), 4 listening (two short clips)","markedBy":"App"},{"part":"Speaking sample","time":"3 min","what":"''Tell me about your job or studies, and what you''d like to be doing in two years'' time.'' 60 seconds, 30 seconds to plan.","markedBy":"AI, on the placement scale"},{"part":"Writing sample","time":"15 min","what":"''Write 80–100 words about a recent trip or event: what happened and what you enjoyed most.''","markedBy":"AI, on the placement scale"}],"questionBlueprint":[{"level":"A2","questions":6,"focus":"Past simple, comparatives, can / have to, everyday vocabulary"},{"level":"B1","questions":8,"focus":"Present perfect vs past simple, future forms, first conditional, modals, B1 vocabulary"},{"level":"B1+","questions":6,"focus":"Past perfect, passive, second conditional, relative clauses, collocations"},{"level":"B2","questions":4,"focus":"Reported speech, third conditional, modals of deduction, B2 vocabulary"}],"bands":[{"band":"A2","description":"''Getting there'' on most criteria: short, simple sentences; frequent errors that sometimes block meaning."},{"band":"B1","description":"''On target'' on most criteria: the task is done clearly; errors do not block meaning."},{"band":"B1+","description":"''Beyond target'' on most criteria: some range and longer, linked sentences."},{"band":"B2","description":"''Beyond target'' on all criteria: wide range, accurate complex sentences, well organised."}],"decisionRules":[{"outcome":"Foundation course","testScore":"0–11","samples":"Or both samples at A2, whatever the test score."},{"outcome":"Stage 1","testScore":"12–18","samples":"At least one sample at B1 or above."},{"outcome":"Stage 2","testScore":"19–24","samples":"Both samples at B1+ or above."}],"borderline":"If the score is within one point of a boundary, or the test and samples point to different results, place the learner in the lower option and tell them they can take a short move-up check after week 2. Where a teacher is involved, they review borderline cases first.","learnerChoice":"A learner placed in Stage 2 may choose to start at Stage 1. A learner placed in the foundation course is shown why, with links to suitable A2 material.","efSetCrossCheck":"If the EF SET result differs from the placement by a full CEFR level or more, the placement is flagged for review; it is not changed automatically."},"checkpoint1":{"intro":"A course checkpoint, not a CEFR placement or certification test. It assesses B1 grammar, a short spoken narrative and a 150-word piece, and is reported beside the learner''s EF SET starting test.","quiz":{"scoredItems":20,"reserveItems":4,"blueprint":"Four Main items and one Light item per week, written separately from the practice item bank so the checkpoint tests learning, not memory of practice items. Order: weeks 1–4, Main then Light. Exclude stretch tasks.","delivery":"Each item is auto-marked; the reason is shown only after the whole checkpoint is submitted. Short scenarios and answer keys allow valid variants; if two options are grammatical, ask which better expresses the stated meaning or accept both.","reporting":"Report results by skill and recommend a specific practice item."},"items":[{"id":"CP1-01","week":1,"target":"Main: finished time","prompt":"We ___ the Colosseum when we were in Rome in 2019.","options":["visited","have visited"],"key":"visited","reason":"''In 2019'' is a finished time."},{"id":"CP1-02","week":1,"target":"Main: past to now","prompt":"My brother ___ three different jobs since he left university.","options":["had","has had"],"key":"has had","reason":"''Since he left'' connects the past to now."},{"id":"CP1-03","week":1,"target":"Main: background","prompt":"The sun ___ (shine) when we left the hotel.","options":[],"key":"was shining","reason":"Background to the main event."},{"id":"CP1-04","week":1,"target":"Main: sequence","prompt":"When I opened the fridge, I realised someone ___ (eat) my cake.","options":[],"key":"had eaten","reason":"It happened before I opened the fridge."},{"id":"CP1-05","week":1,"target":"Light","prompt":"As a teenager, I ___ have very long hair.","options":["used to","would"],"key":"used to","reason":"''Have'' (possession) is a state, so would is not possible."},{"id":"CP1-06","week":2,"target":"Main: intention","prompt":"A: Any plans for the summer? B: I ___ visit my cousins in Ireland, but I haven''t booked anything yet.","options":["''m going to","''m visiting"],"key":"''m going to","reason":"An intention with nothing arranged yet."},{"id":"CP1-07","week":2,"target":"Main: arrangement","prompt":"We ___ (fly) to Lisbon on Friday. The tickets are in my bag.","options":[],"key":"''re flying (are flying)","reason":"A fixed arrangement."},{"id":"CP1-08","week":2,"target":"Main: time clause","prompt":"I''ll send you the photos when I ___ home.","options":["get","''ll get"],"key":"get","reason":"After ''when'', use the present simple for the future."},{"id":"CP1-09","week":2,"target":"Main: time clause","prompt":"As soon as the film ___ (finish), we''ll go for dinner.","options":[],"key":"finishes","reason":"After ''as soon as'', use the present simple for the future."},{"id":"CP1-10","week":2,"target":"Light","prompt":"If I ___ the lottery, I''d buy a house by the sea.","options":["won","win"],"key":"won","reason":"Second conditional: an imagined situation."},{"id":"CP1-11","week":3,"target":"Main: obligation","prompt":"In the UK, you ___ drive on the left.","options":["have to","don''t have to"],"key":"have to","reason":"It is a rule."},{"id":"CP1-12","week":3,"target":"Main: advice","prompt":"If you want to improve your English, you ___ read a little every day.","options":["should","mustn''t"],"key":"should","reason":"Advice."},{"id":"CP1-13","week":3,"target":"Main: ability","prompt":"My grandmother ___ (can / not / use) a smartphone, so we phone her.","options":[],"key":"can''t use (cannot use)","reason":"Ability, negative."},{"id":"CP1-14","week":3,"target":"Main: permission","prompt":"___ I leave my bag here while I go to the toilet?","options":["Can","Must"],"key":"Can (Could)","reason":"Asking for permission."},{"id":"CP1-15","week":3,"target":"Light","prompt":"Put the words in order: Where / you / do / work?","options":[],"key":"Where do you work?","reason":"Auxiliary before the subject."},{"id":"CP1-16","week":4,"target":"Main: present passive","prompt":"Cheese ___ (make) from milk.","options":[],"key":"is made","reason":"A general fact; the cheese is the focus."},{"id":"CP1-17","week":4,"target":"Main: present passive","prompt":"Most of the city''s buses ___ by electricity now.","options":["are powered","power"],"key":"are powered","reason":"Something powers the buses."},{"id":"CP1-18","week":4,"target":"Main: past passive","prompt":"The first email ___ (send) in 1971.","options":[],"key":"was sent","reason":"Past passive."},{"id":"CP1-19","week":4,"target":"Main: past passive","prompt":"Our flight ___ because of the snow.","options":["was cancelled","cancelled"],"key":"was cancelled","reason":"The airline cancelled it."},{"id":"CP1-20","week":4,"target":"Light","prompt":"This is the hotel ___ we stayed last summer.","options":["where","who"],"key":"where","reason":"''Where'' for a place followed by a full clause."}],"reserves":[{"id":"CP1-R1","week":1,"target":"reserve","prompt":"I ___ (not / see) her since the wedding.","options":[],"key":"haven''t seen (have not seen)","reason":"Up to now with since."},{"id":"CP1-R2","week":2,"target":"reserve","prompt":"Don''t worry, I ___ (call) you before I ___ (leave).","options":[],"key":"''ll call ... leave","reason":"Will for the promise; present simple after before."},{"id":"CP1-R3","week":3,"target":"reserve","prompt":"You ___ (not / have to) come to the party if you''re tired.","options":[],"key":"don''t have to","reason":"It isn''t necessary."},{"id":"CP1-R4","week":4,"target":"reserve","prompt":"The Alhambra ___ (visit) by millions of people every year.","options":[],"key":"is visited","reason":"Present passive with by."}],"reserveUse":"Reserves replace an item that pilot data shows is unclear, or form a retake for learners repeating the checkpoint.","writing":{"prompts":[{"label":"A. A change I got used to","text":"Describe how life was before a change, what happened, what was difficult, and how things are now."},{"label":"B. A note for a visitor","text":"A friend is visiting your town for a weekend. Recommend what to see: include a regular event or custom, one fact about a place''s past, a comparison, and one piece of advice."}],"conditions":[{"id":"length","setting":"Length","value":"150 words (130–170 accepted)"},{"id":"time","setting":"Time","value":"30 minutes, with a visible timer"},{"id":"where","setting":"Where","value":"In the app; pasting disabled; no phrase bank or model"},{"id":"attempts","setting":"Attempts","value":"One submission; no revise-and-retry"},{"id":"marking","setting":"Marking","value":"AI bands on the four writing criteria straight away; a teacher confirms where one is involved, and the teacher''s mark counts"}],"onTarget":"''On target'' or better on at least three criteria, task achievement not ''Getting there''. Results guide practice; they never block week 5."},"result":{"intro":"Results are reported by part and by week, never as pass or fail. Learners continue to week 5 whatever their result; the checkpoint guides practice, it does not block progress.","thresholds":[{"part":"Quiz","onTarget":"14 of 20 or more (70%)"},{"part":"Speaking","onTarget":"''On target'' or better on at least three criteria, and task achievement not at ''Getting there''"},{"part":"Writing","onTarget":"''On target'' or better on at least three criteria, and task achievement not at ''Getting there''"}],"practiceLinks":"Each part below target links to the matching practice: weak quiz items to that week''s extra items and grammar clinic, speaking to the week''s shadowing and conversation, writing to a revise-and-retry task on the same prompt."},"calibration":["A second teacher checks every checkpoint item for a single correct answer and accepted variants.","Check the existing 24 placement questions against the blueprint (6 A2, 8 B1, 6 B1+, 4 B2) and replace those that do not fit.","Mark 10–20 sample texts and recordings by hand and compare with the AI''s bands; adjust prompts until they agree on at least 8 in 10.","After 30 placed learners, compare placement with EF SET results and adjust the cut scores (11/12 and 18/19).","Review any checkpoint item that more than 90% or fewer than 30% of pilot learners answer correctly.","Confirm the checkpoint thresholds (70% quiz, three of four criteria) against teacher judgement of pilot learners."],"speaking":{"status":"pilot draft — pending second-teacher review","intro":"After week 4, learners record one short spoken narrative under checkpoint conditions, marked with the same four descriptors.","prompt":"Talk about a time when you had to adapt to something new: a job, a place, a course or a routine. What was it like before, what happened, and how are things now? If you like, say what you would tell someone in the same situation.","conditions":[{"setting":"Planning","value":"1 minute; notes allowed, no phrase bank or model"},{"setting":"Length","value":"60-90 seconds"},{"setting":"Attempts","value":"One recording; no retry (practice tasks allow retries, checkpoints do not)"},{"setting":"Marking","value":"AI bands on the four criteria straight away; a teacher confirms where one is involved, and the teacher''s mark counts"},{"setting":"On target","value":"\"On target\" or better on at least three of the four criteria, with no criterion at \"Getting there\" for task achievement"},{"setting":"Language it draws on","value":"Weeks 1-4: narrative tenses, present perfect, used to / would, modals for advice; featured vocabulary from any of the four weeks"}],"transferNote":"The prompt is new, so it tests transfer rather than memory of a practised answer."}},"status":"pilot draft — pending second-teacher review","sources":["Writing descriptors, placement and checkpoint 1 (21 Nov 2026)","Fluency Studio: Weeks 1–4 Speaking Content (21 Nov 2026)"]}'::jsonb->'placement'),
